window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[175]={"id":"175","numero":175,"titre":"Voyage en pays tropical de l'enfant et de l'adulte","objectifs":[{"id":"175-1","rang":"A","rubrique":"Définition","titre":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","contenu":"<div class=\"notion-course\"><p>L'évaluation pré-voyage repose sur <strong>3 paramètres</strong> à croiser systématiquement pour estimer le risque sanitaire individuel.</p>\n      <table>\n        <thead><tr><th>Paramètre</th><th>Éléments à analyser</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Destination</strong></td>\n            <td>Situation <span>sanitaire et politique</span> du pays ; saison ; zones visitées (<span>rurales</span> ou <span>urbaines</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Voyage</strong></td>\n            <td><strong>Modalités :</strong> moyen de transport ; conditions de logement ; activités prévues (baignade, randonnée) ; voyage organisé ou aventureux<br>\n            <strong>Durée :</strong> une exposition <span>ponctuelle</span> suffit pour le <span><span class=\"nc-pink nc-bold\">paludisme</span></span> (anophèle), la <span><span class=\"nc-pink nc-bold\">fièvre jaune</span></span> et la <span><span class=\"nc-pink nc-bold\">dengue</span></span> (Aedes), le <span>VIH</span> (<span>contact</span> sexuel) ; une exposition <span>prolongée</span> est nécessaire pour la <span><span class=\"nc-orange\">lèpre</span></span> et <span>les</span> <span><span class=\"nc-orange\">filarioses</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Voyageur</strong></td>\n            <td>Âge ; <span>grossesse</span> ; <span>comorbidités</span> ; statut <span>immunitaire et vaccinal</span> ; budget — vaccins et <span>chimioprophylaxie</span> <strong>non remboursés</strong></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Voyageurs particulièrement à risque :</strong></p>\n      <ul>\n        <li>Adultes jeunes en <span>voyage non organisé</span> vers certaines destinations (Afrique subsaharienne, Inde), sur plusieurs semaines</li>\n        <li>Sujets <span>émigrés</span> effectuant un séjour dans leur pays d'origine</li>\n        <li><span><span class=\"nc-purple_bg\">Immunodéprimés</span></span></li>\n      </ul>\n      <p><strong>Sources numériques d'information :</strong> <span>les</span> recommandations aux voyageurs sont émises par le <span><span class=\"nc-yellow_bg\">Comité des maladies liées aux voyages et des maladies d'importation (CMVI)</span></span><span class=\"nc-yellow_bg\"> du HCSP</span>, publiées dans le <span><span class=\"nc-blue_bg\">Bulletin épidémiologique hebdomadaire</span> (BEH)</span> et actualisées selon la situation internationale.</p>\n      <div class=\"callout callout-warn\"><strong><span>Mortalité</span> du voyageur.</strong> <span>Les</span> causes <strong>non infectieuses</strong> dominent : <span><span class=\"nc-red_bg\">pathologies cardio-vasculaires</span></span> (&gt;<span> 50 %</span> des décès), <span class=\"nc-blue_bg\">traumatologie</span>. Les pathologies infectieuses ne représentent que <span>1-3 %</span> des décès — par ordre de fréquence : <span><span class=\"nc-red nc-bold\">diarrhée</span></span> ++ &gt; <span class=\"nc-purple_bg\">infections des voies aériennes supérieures</span> &gt; <span class=\"nc-purple_bg\">dermatoses</span> &gt; <span class=\"nc-purple_bg\">infections systémiques</span> (<span><span class=\"nc-pink nc-bold\">paludisme</span></span>).</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":2},{"id":"175-2","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","contenu":"<div class=\"notion-course\"><p><span>Les</span> conseils de prévention, donnés en <strong>consultation pré-voyage</strong>, se déclinent par domaine d'exposition.</p>\n      <table>\n        <thead><tr><th>Domaine</th><th>Conseils</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Maladie chronique</strong></td>\n            <td>Évaluation avant le départ ; partir avec des documents médicaux (en anglais si besoin) ; le voyage peut être <span>contre-indiqué</span> selon <span>les</span> cas</td>\n          </tr>\n          <tr>\n            <td><strong>Hygiène alimentaire</strong></td>\n            <td>Prévient <span>les</span> maladies à transmission <span>oro-fécale</span> (<span><span class=\"nc-red nc-bold\">turista</span></span>, <span><span class=\"nc-red nc-bold\">typhoïde</span></span>, <span><span class=\"nc-red nc-bold\">VHA</span></span>, <span><span class=\"nc-red nc-bold\">VHE</span></span>, <span class=\"nc-red nc-bold\">parasitoses intestinales</span>) :<br>\n            • lavage des mains après les toilettes et avant les repas (SHA en l'absence de point d'eau)<br>\n            • eau en bouteille encapsulée, ou rendue potable (filtration, ébullition, désinfectant)<br>\n            • lait pasteurisé ou bouilli ; viande et poisson bien cuits, consommés chauds<br>\n            • peler les fruits ; éviter crudités, coquillages, buffets froids, glaçons et glaces<br>\n            • se méfier de la <span><span class=\"nc-red nc-bold\">ciguatera</span></span> (toxicité des gros poissons de mer)</td>\n          </tr>\n          <tr>\n            <td><strong>Prévention sexuelle</strong></td>\n            <td>Préservatif conseillé ; en cas de conduite sexuelle à risque, consulter au plus tôt (<span>&lt; 24 h</span>) pour un éventuel <span>traitement post-exposition</span></td>\n          </tr>\n          <tr>\n            <td><strong>Protection anti-vectorielle</strong></td>\n            <td>Culex : notamment West Nile et <span class=\"nc-brown_bg\">encéphalite japonaise</span>. Les tiques transmettent notamment borréliose de Lyme, certaines <span class=\"nc-orange_bg\">rickettsioses</span> et <span class=\"nc-brown_bg\">encéphalite à tiques</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Baignade et sol</strong></td>\n            <td>Pas de baignade en eau douce stagnante (<span><span class=\"nc-orange_bg nc-bold\">schistosomoses</span></span>, <span><span class=\"nc-orange_bg nc-bold\">leptospirose</span></span>) ; <span class=\"nc-green_bg\">ne pas marcher pieds nus en extérieur</span> (<span>anguillulose</span>, <span>ankylostomose</span>) ; ne pas s'allonger sur le <span class=\"nc-green_bg nc-bold\">sable</span> <span class=\"nc-green_bg\">de certaines plages</span> des Antilles ; repasser au fer chaud le linge séché au soleil (<span>myiase</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Soleil et chaleur</strong></td>\n            <td>Pas d'<span>exposition solaire</span> avant l'âge de <span>1 an</span> ; crème solaire <span>FPS ≥ 30</span> réappliquée toutes <span>les</span> <span>2 h</span> ; lunettes enveloppantes à verres filtrants <span>CE 3 ou 4</span></td>\n          </tr>\n          <tr>\n            <td><strong>Animaux</strong></td>\n            <td>Chaussures fermées et pantalons longs en végétation dense ; secouer habits, draps, sacs de couchage et chaussures (scorpions, serpents) ; ne pas approcher <span>les</span> animaux errants (<span>rage</span>) ; éviter les <span class=\"nc-red nc-bold\">volailles en Asie du Sud-Est</span> (<span>grippe aviaire</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Trousse du voyageur</strong> (l'antipaludique préventif et <span>les</span> répulsifs ne sont <span>pas remboursés</span>) :</p>\n      <ul>\n        <li><strong>Anti-vectoriel :</strong> répulsifs contre <span>les</span> arthropodes ; antipaludique à usage préventif si nécessaire</li>\n        <li><strong>Médicaments :</strong> <span>paracétamol</span> (<span>antalgique</span> / antipyrétique) ; <span><span class=\"nc-pink_bg\">racécadotril</span></span> (<span class=\"nc-pink_bg\">antidiarrhéique antisécrétoire</span>) ; antiémétique ; antibiotique en l'absence de soins locaux ; <span>anti-H1</span> de dernière génération</li>\n        <li><strong>Autres produits :</strong> SHA ; produit de désinfection de l'eau de boisson ; <span>soluté de réhydratation orale</span> ; écran solaire 50+ ; sérum physiologique monodose ; antiseptique, pansements et sutures adhésives ; <span class=\"nc-blue_bg\">bande de contention</span>, <span class=\"nc-blue_bg\">thermomètre</span>, <span class=\"nc-blue_bg\">pince à épiler</span>, <span class=\"nc-blue_bg\">préservatifs</span>, masques</li>\n        <li><strong>Ordonnance :</strong> traitement habituel rédigé en <span>DCI</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span>Chimioprophylaxie</span> antipaludique (rappel).</strong> Toujours en association à la protection anti-vectorielle ; <span>non remboursée</span> et <strong>ne protège pas à<span> 100 %</span></strong>. Molécules recommandées pour l'Afrique subsaharienne :\n        <ul>\n          <li><span><span class=\"nc-pink_bg\">Atovaquone-proguanil</span></span> : prise <strong><span class=\"nc-green_bg\">durant le séjour</span></strong>, quotidienne, poursuivie <span><span class=\"nc-green_bg\">1 semaine</span></span> après le retour (<span class=\"nc-green nc-bold\">agit sur </span><span><span class=\"nc-green nc-bold\">les</span></span><span class=\"nc-green nc-bold\"> </span><strong><span class=\"nc-green nc-bold\">formes hépatiques</span></strong>, d'où la durée réduite) ; dès <span>≥ 11 kg</span></li>\n          <li><span><span class=\"nc-pink_bg\">Méfloquine</span></span> : début <span><span class=\"nc-red_bg\">10 jours</span></span><span class=\"nc-red_bg\"> avant le départ</span> (test de tolérance, demi-vie longue), prise hebdomadaire, poursuivie <span><span class=\"nc-orange_bg\">3 semaines</span></span> après le retour ; dès <span>≥ 15 kg</span> — <span>CI : ATCD de <span class=\"nc-red nc-bold\">dépression</span>, ATCD de <span class=\"nc-red nc-bold\">convulsion</span>, prise de <span class=\"nc-orange_bg\">valproate de sodium</span></span></li>\n          <li><span>Doxycycline</span> : prise <strong><span class=\"nc-green_bg\">durant le séjour</span></strong>, quotidienne, poursuivie <span><span class=\"nc-red_bg\">4 semaines</span></span> après le retour ; dès <span>≥ 8 ans</span></li>\n        </ul>\n        Mises à jour chaque année dans le <span>BEH</span> (HCSP). <em>📎 cf. item 170 — <span>Paludisme</span></em> pour le détail complet.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":1},{"id":"175-3","rang":"A","rubrique":"Prise en charge","titre":"Identifier les personnes avec une fragilité particulière","contenu":"<div class=\"notion-course\"><ul><li>La prévention associe protection contre les piqûres et, selon destination précise, saison, durée, conditions du séjour et terrain, chimioprophylaxie. Aucun moyen ne protège à 100 % ; toute fièvre au retour impose d’évoquer le paludisme en urgence.</li><li>Moustiquaire imprégnée, vêtements couvrants et répulsif cutané adapté au produit, à l’âge et à la grossesse. L’imprégnation insecticide des vêtements n’est plus recommandée pour le voyageur ; ne pas la confondre avec celle des moustiquaires.</li><li>Consulter les tableaux HCSP 2026 par pays et le RCP ; ne pas déduire une prophylaxie d’un continent seul. L’enfant et la femme enceinte nécessitent une évaluation spécifique.</li><li>Choisir le répulsif selon son AMM et son RCP, avec concentration et fréquence adaptées ; éviter mains et muqueuses du jeune enfant. Pas de règle unique de concentration ou d’âge valable pour tous les produits. Écarter les huiles essentielles et dispositifs sans efficacité établie.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"175-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les principales infections acquises au cours d’un voyage en zone tropicale","contenu":"<div class=\"notion-course\"><ul><li><span class=\"nc-pink_bg\">Atovaquone–proguanil</span> : début la veille de l’entrée en zone exposée, prise quotidienne et poursuite sept jours après la sortie. Dose selon poids ; l’usage entre 5 et moins de 11 kg est hors AMM et relève d’une prescription adaptée.</li><li>Doxycycline : début la veille, prise quotidienne et poursuite 28 jours après la sortie ; précautions œsophagiennes et photosensibilisation. Pour cette prophylaxie prolongée : contre-indication avant huit ans, pendant les deuxième et troisième trimestres et l’allaitement ; premier trimestre déconseillé.</li><li><span class=\"nc-pink_bg\">Méfloquine</span> : désormais en dernière intention, après évaluation des contre-indications et risques neuropsychiatriques. Début au moins dix jours avant le départ, prise hebdomadaire, poursuite trois semaines après la sortie selon HCSP 2026.</li><li>Pas de prescription uniforme : interactions, poids, grossesse, fonction rénale, tolérance et adhésion guident le choix. Un traitement de réserve est une stratégie exceptionnelle et ne remplace ni la prophylaxie indiquée ni l’accès aux soins.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":1},{"id":"175-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les vaccinations spécifiques du voyageur","contenu":"<div class=\"notion-course\"><p>La <span>vaccination</span> du voyageur combine <strong>3 catégories</strong> : mise à jour des vaccins de routine, vaccins <strong><span class=\"nc-red nc-bold\">obl</span><span><span class=\"nc-red nc-bold\">iga</span></span><span class=\"nc-red nc-bold\">toires</span></strong>, vaccins <strong><span class=\"nc-blue nc-bold\">recommandés</span></strong>. Vaccins et <span>chimioprophylaxie</span> ne sont <span>pas remboursés</span>.</p>\n      <p><strong>Vaccins de routine</strong></p>\n      <ul>\n        <li>Mise à jour du <span>calendrier vaccinal</span> avant le départ</li>\n        <li>Chez l'enfant non vacciné, en cas de séjour prolongé (<span>&gt; 1 mois</span>) en pays de forte endémie : <span><span class=\"nc-purple_bg\">BCG</span></span> ; <span class=\"nc-pink_bg\">vaccin</span> <span>anti-rougeoleux</span> (dès <span>6 mois</span>, <span class=\"nc-pink_bg\">vaccin</span> monovalent) ; <span class=\"nc-yellow_bg\">vaccin contre l'</span><span><span class=\"nc-yellow_bg\">hépatite B</span></span></li>\n        <li>Vaccination antigrippale selon calendrier, terrain, saison et destination. Pour un vaccin adapté à l’autre hémisphère, vérifier disponibilité et circuit actuel ; ne pas reprendre sans contrôle l’ancien terme ATU nominative.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Vaccins <span class=\"nc-red nc-bold\">obl</span><span><span class=\"nc-red nc-bold\">iga</span></span><span class=\"nc-red nc-bold\">toires</span>.</strong>\n        <strong><span><span class=\"nc-pink nc-bold\">Fièvre</span></span><span class=\"nc-pink nc-bold\"> jaune</span> (anti-amarile) :</strong> <span class=\"nc-red_bg\">vaccin </span><span><span class=\"nc-red_bg\">vivant atténué</span></span> ; <span>CI <span class=\"nc-red nc-bold\">grossesse</span></span> (déconseillé) et <span><span class=\"nc-red nc-bold\">immunodéprimé</span></span> (possible dans le <span>VIH</span> si <span>CD4</span> <span>&gt; 200/mm³</span> et <span>&gt; 15 %</span> de <span>lymphocytes</span>) ; <span class=\"nc-red nc-bold\">obligatoire</span> ou recommandé pour l'<span class=\"nc-green_bg\">Afrique intertropicale</span> et la <span class=\"nc-green_bg\">région amazonienne</span>, <span>absent en Asie et en <span class=\"nc-green_bg\">Océanie</span></span> ; authentifié par un <span class=\"nc-yellow_bg\">médecin d'un Centre agréé de Vaccinations Internationales</span> sur le carnet international ; efficace <span>10 jours</span> après l'injection et pour <strong><span class=\"nc-red nc-bold\">toute la vie</span></strong> (sauf injection avant <span>2 ans</span> ou pendant la <span><span class=\"nc-red nc-bold\">grossesse</span></span>).<br>\n        <strong><span>Méningocoque</span> ACYW conjugué :</strong> <span class=\"nc-red nc-bold\">obligatoire</span> pour le <strong>pèlerinage en Arabie Saoudite</strong>.</div>\n      <p><strong>Vaccins <span class=\"nc-blue nc-bold\">recommandés</span></strong></p>\n      <table>\n        <thead><tr><th>Vaccin</th><th>Type · âge</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><span>Hépatite B</span></td><td>Vaccin inerte (protéines recombinantes)</td><td>Séjour fréquent ou prolongé en zone d'endémie</td></tr>\n          <tr><td><span>Hépatite A</span></td><td><span class=\"nc-pink_bg\">Vaccin</span> inerte ; dès <span><span class=\"nc-pink nc-bold\">≥ 1 an</span></span></td><td>Séjour en pays à hygiène précaire, <strong><span class=\"nc-red nc-bold\">quelles que soient </span><span><span class=\"nc-red nc-bold\">les</span></span><span class=\"nc-red nc-bold\"> conditions du séjour</span></strong></td></tr>\n          <tr><td><span>Typhoïde</span></td><td><span class=\"nc-pink_bg\">Vaccin</span> <span>polyosidique</span> ; efficacité <span>60 %</span> ; rappel tous <span>les</span> <span><span class=\"nc-pink nc-bold\">3 ans</span></span> ; dès <span><span class=\"nc-pink nc-bold\">≥ 2 ans</span></span></td><td>Séjours prolongés en pays à bas niveau d'hygiène (<span class=\"nc-green_bg\">sous-continent indien</span> ++)</td></tr>\n          <tr><td><span>Rage</span> (pré-exposition)</td><td><span class=\"nc-pink_bg\">Vaccin</span> inerte ; <span class=\"nc-pink nc-bold\">dès l'âge de la marche</span></td><td><span class=\"nc-yellow_bg\">Séjour prolongé, aventureux</span> ou isolé en zone à risque (Asie, Afrique, <span class=\"nc-red_bg\">Amérique du Sud</span>)</td></tr>\n          <tr><td><span>Méningocoque ACYW</span></td><td>Conjugué</td><td><span class=\"nc-red nc-bold\">Ceinture de la </span><span><span class=\"nc-red nc-bold\">méningite</span></span><span class=\"nc-red nc-bold\"> en Afrique</span> en saison sèche (<span><span class=\"nc-red nc-bold\">novembre-juin</span></span>) ; <span>contact</span> étroit et prolongé avec la population</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Vaccins de l'enfant voyageur</strong> — âge minimal et régions :</p>\n      <table>\n        <thead><tr><th>Vaccin</th><th>Âge minimal</th><th>Régions / commentaire</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-pink nc-bold\">Fièvre</span></span><span class=\"nc-pink nc-bold\"> jaune</span></td><td><span>9 mois</span> (<span>6 mois</span> si épidémie)</td><td>Régions intertropicales d'Afrique et d'<span class=\"nc-red_bg\">Amérique du Sud</span> ; <span>CI <span class=\"nc-red nc-bold\">immunodéprimé</span></span>, <span>allergie</span> à l'œuf</td></tr>\n          <tr><td><span>Hépatite</span> A</td><td><span>1 an</span></td><td>Toutes destinations tropicales ou peu hygiéniques — à proposer largement</td></tr>\n          <tr><td><span>Méningocoque</span> ACYW</td><td><span>1 an</span></td><td>Afrique subsaharienne en saison sèche</td></tr>\n          <tr><td>Rage</td><td><span class=\"nc-pink nc-bold\">Dès l'âge de la marche</span></td><td>Asie, <span class=\"nc-red_bg\">Amérique du Sud</span>, Afrique ; séjour isolé ou prolongé</td></tr>\n          <tr><td>Typhoïde</td><td><span>2 ans</span></td><td><span class=\"nc-green_bg\">Sous-continent indien</span>, <span class=\"nc-green_bg\">Asie du Sud-Est</span>, Afrique ; protection limitée (<span>60-80 %</span>)</td></tr>\n          <tr><td><span><span class=\"nc-brown_bg\">Encéphalite</span></span><span class=\"nc-brown_bg\"> japonaise</span></td><td><span>2 mois</span></td><td><span class=\"nc-green_bg\">Asie du Sud-Est</span>, <span class=\"nc-green_bg\">sous-continent indien</span> ; activités extérieures près des rizières à la saison des pluies</td></tr>\n          <tr><td><span><span class=\"nc-brown_bg\">Encéphalite</span></span><span class=\"nc-brown_bg\"> à tiques</span></td><td><span>1 an</span></td><td>Europe centrale, orientale et septentrionale ; du printemps à novembre</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Rang C</strong> (pour mémoire) : <span><span class=\"nc-brown_bg\">choléra</span></span> (personnel de santé en période d'épidémie) ; <span><span class=\"nc-brown_bg\">encéphalite japonaise</span></span> ; <span><span class=\"nc-brown_bg\">encéphalite à tiques</span></span>.</p>\n      <div class=\"callout callout-info\"><strong>Mnémo.</strong> « Pas de <span><span class=\"nc-pink nc-bold\">fièvre</span></span><span class=\"nc-pink nc-bold\"> jaune</span> chez <span>les</span> jaunes » — le <span class=\"nc-pink_bg\">vaccin</span> anti-amarile ne concerne <strong>pas</strong> l'Asie ni l'<span class=\"nc-green_bg\">Océanie</span>, où la <span><span class=\"nc-pink nc-bold\">fièvre</span></span><span class=\"nc-pink nc-bold\"> jaune</span> est absente.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span>Vaccination</span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-pink nc-bold\">Fièvre jaune</span> : certificat international généralement valable à vie ; les indications médicales éventuelles de rappel sont distinctes des règles du certificat. Vaccins du voyage selon exposition et calendrier 2026, y compris ROR anticipé dans certaines situations ; une dose avant douze mois ne remplace pas les deux doses ultérieures. Vérifier l’âge autorisé de chaque spécialité.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":6},{"id":"175-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les indications d’une sérologie hépatite A chez un patient à risque d’exposition antérieure","contenu":"<div class=\"notion-course\"><p>Le <span>VHA</span> est une <span>maladie immunisante</span> : un sujet ayant déjà contracté l'<span>hépatite</span> A est protégé à vie. La <span>sérologie VHA</span> permet d'identifier <span>les</span> patients <strong>déjà immunisés</strong>, à qui une <span>vaccination</span> serait inutile.</p>\n      <p>Indications d'une <span>sérologie VHA</span> <strong>avant de décider de vacciner</strong> (recherche d'une <span>immunité ancienne</span>, chez un patient à risque d'exposition antérieure) :</p>\n      <ul>\n        <li>Personnes <strong>nées en France avant 1945</strong> (<span>&gt; 75 ans</span>)</li>\n        <li>Personnes ayant <strong>vécu dans un pays d'endémie</strong></li>\n        <li>Personnes signalant un <strong>antécédent d'<span>ictère</span></strong></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"175-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les conseils de prévention vis-à-vis des parasitoses à transmission éco-orale ou transcutanée","contenu":"<div class=\"notion-course\"><p><span>Les</span> parasitoses du voyageur se préviennent selon leur <strong>voie de transmission</strong> — deux mécanismes distincts.</p>\n      <div class=\"callout callout-info\"><strong>Transmission éco-orale</strong> (mains, eau, aliments souillés). Concerne <span>les</span> <span><span class=\"nc-red nc-bold\">parasitoses intestinales</span></span> (<span>protozooses</span>, helminthoses). Prévention : lavage des mains, eau encapsulée ou traitée, éviter les crudités et aliments souillés, peler les fruits.</div>\n      <div class=\"callout callout-info\"><strong>Transmission transcutanée</strong> (pénétration active de la larve à travers la peau). Prévention :\n        <ul>\n          <li>Pas de baignade en eau douce → <span><span class=\"nc-orange_bg nc-bold\">schistosomoses</span></span></li>\n          <li><span class=\"nc-green_bg\">Ne pas marcher pieds nus en extérieur</span> → <span>anguillulose (<span class=\"nc-orange_bg nc-bold\">strongyloïdose)</span></span>, <span><span class=\"nc-orange_bg nc-bold\">ankylostomose</span></span><span class=\"nc-orange_bg nc-bold\"> (</span><span><span class=\"nc-orange_bg nc-bold\">larva migrans cutanée</span></span><span class=\"nc-orange_bg nc-bold\">)</span></li>\n          <li><span class=\"nc-green_bg\">Ne pas s'allonger directement sur le</span> <span class=\"nc-green_bg nc-bold\">sable</span> contaminé <span class=\"nc-green_bg\">de certaines plages</span> → <span>ankylostomose</span></li>\n          <li>Repasser au fer chaud le linge séché au soleil → <span>myiase</span></li>\n        </ul>\n      </div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":1},{"id":"175-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales maladies d’importation responsables de fièvre","contenu":"<div class=\"notion-course\"><p>Devant une <span>fièvre</span> au retour des tropiques, un petit nombre de <strong>maladies d'importation</strong> concentre l'essentiel des diagnostics. Chacune a une orientation clinico-<span>biologique</span> propre.</p>\n      <table>\n        <thead><tr><th>Maladie</th><th>Contamination</th><th>Orientation clinique</th><th>Biologie</th><th>Confirmation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-pink nc-bold\">Paludisme</span></span></strong></td>\n            <td>Anophèle</td>\n            <td><span class=\"nc-blue_bg\">Troubles digestifs</span> et neurologiques ; <span><span class=\"nc-green nc-bold\">splénomégalie</span></span><span class=\"nc-green nc-bold\">,</span> <span><span class=\"nc-purple nc-bold\">hépatomégalie</span></span></td>\n            <td><span><span class=\"nc-orange_bg\">Thrombopénie</span></span> ++ ; anémie ; <span class=\"nc-orange_bg\">leucopénie</span> ; <span>CRP</span> élevée ; <span>ALAT</span> &lt; 5N</td>\n            <td><span>Goutte épaisse</span> + frottis mince ; TDR ; biologie moléculaire</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-green_bg\">Arboviroses</span></span></strong> (dengue ++)</td>\n            <td>Aedes</td>\n            <td><span><span class=\"nc-blue_bg\">Myalgies</span></span>, <span><span class=\"nc-blue_bg\">arthralgies</span></span>, <span><span class=\"nc-blue_bg\">rash</span></span><span class=\"nc-blue_bg\">,</span> <span><span class=\"nc-green nc-bold\">splénomégalie</span></span></td>\n            <td><span class=\"nc-orange_bg\">Leucopénie</span> ++ ; <span class=\"nc-orange_bg\">thrombopénie</span> ++ ; <span>CRP</span> basse ; <span>ALAT</span> &lt; 5N</td>\n            <td><span><span class=\"nc-blue_bg\">PCR</span></span> durant <span>les</span> <span><span class=\"nc-pink nc-bold\">5 premiers jours</span></span><span class=\"nc-pink nc-bold\"> de </span><span><span class=\"nc-pink nc-bold\">fièvre</span></span> ; <span><span class=\"nc-blue_bg\">sérologie</span></span> au-delà</td>\n          </tr>\n          <tr>\n            <td><strong><span>Hépatites virales</span></strong></td>\n            <td>Oro-fécale (<span>VHA</span>)</td>\n            <td><span class=\"nc-blue_bg\">Troubles digestifs</span> ; <span><span class=\"nc-red nc-bold\">ictère</span></span> ; <span><span class=\"nc-purple nc-bold\">hépatomégalie</span></span> ; <span><span class=\"nc-orange nc-bold\">urticaire</span></span></td>\n            <td>Leucopénie ; <span>CRP</span> basse ; <span>ALAT &gt; 10N</span></td>\n            <td><span>Sérologies</span></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-yellow_bg\">Fièvre</span> <span class=\"nc-red nc-bold\">typhoïde</span></span></strong></td>\n            <td>Oro-fécale (réservoir <span class=\"nc-yellow_bg nc-bold\">strictement humain</span>)</td>\n            <td><span>Céphalées</span> ++ ; insomnie ; <span><span class=\"nc-yellow_bg\">pouls dissocié</span></span> ; <span><span class=\"nc-blue_bg\">splénomégalie</span></span></td>\n            <td>Leucopénie ; <span>CRP</span> élevée ; <span>ALAT</span> &lt; 5N</td>\n            <td><span>Hémocultures</span></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Rickettsioses</span></span></strong></td>\n            <td>Tiques</td>\n            <td><span><span class=\"nc-yellow_bg\">Escarre d'inoculation</span></span> ; <span><span class=\"nc-blue_bg\">éruption</span></span> ; <span><span class=\"nc-orange_bg\">adénopathies</span></span> ; <span><span class=\"nc-blue_bg\">céphalées</span></span></td>\n            <td><span class=\"nc-orange_bg\">Leucopénie</span> ; <span class=\"nc-orange_bg\">thrombopénie</span> ; <span>CRP</span> élevée</td>\n            <td><span><span class=\"nc-blue_bg\">Sérologies</span></span> ; <span><span class=\"nc-blue_bg\">biopsie</span></span><span class=\"nc-blue_bg\"> cutanée puis </span><span><span class=\"nc-blue_bg\">PCR</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-red nc-bold\">Amoebose hépatique</span></span></strong></td>\n            <td>Oro-fécale</td>\n            <td><span><span class=\"nc-purple nc-bold\">Hépatomégalie</span> douloureuse</span></td>\n            <td><span>Hyperleucocytose à PNN</span> ; <span>CRP</span> élevée</td>\n            <td><span>Échographie</span> hépatique ± <span>TDM</span> ; <span>sérologie</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Schistosomose</span></strong> (phase d'invasion)</td>\n            <td>Baignade en eau douce</td>\n            <td><span><span class=\"nc-blue_bg\">Prurit</span></span>, <span><span class=\"nc-orange nc-bold\">urticaire</span></span>, <span>arthralgies</span>, <span><span class=\"nc-purple nc-bold\">hépatomégalie</span></span>, <span>toux</span></td>\n            <td><span><span class=\"nc-blue_bg\">Hyperéosinophilie</span></span> ; <span>CRP</span> élevée</td>\n            <td><span><span class=\"nc-yellow_bg\">Sérologie</span></span><span class=\"nc-yellow_bg\"> en phase d'invasion</span> ; recherche d'œufs (<span class=\"nc-blue nc-bold\">selles</span>, urines) en phase d'état</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Réflexe n°1.</strong> Le <span><span class=\"nc-red_bg\">paludisme à </span><em><span class=\"nc-red_bg\">P. falciparum</span></em></span> est la 1ʳᵉ cause à évoquer devant toute <span>fièvre</span> survenant dans <span>les</span> <span>3 mois</span> suivant le retour d'une zone d'endémie. La <span><span class=\"nc-orange nc-bold\">dengue</span></span> est la 2ᵉ étiologie la plus fréquente.</div>\n      <div class=\"callout callout-warn\"><strong>Ne pas oublier.</strong> Une <span>fièvre</span> au retour peut être <strong>non infectieuse</strong> (MTEV, néoplasie, maladie <span>inflammatoire</span>) ou infectieuse <strong>cosmopolite</strong> (PNA, <span>grippe</span>, pneumopathie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span>Paludisme</span> · 147 — <span>Fièvre</span> aiguë</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"175-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","contenu":"<div class=\"notion-course\"><p>La démarche est systématique : devant toute <span>fièvre</span> au retour, <strong>l'<span>urgence</span> est d'éliminer un <span><span class=\"nc-orange nc-bold\">paludisme</span></span></strong>.</p>\n      <table>\n        <thead><tr><th>Étape</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>Destination précise ; dates du séjour ; <span>durée d'incubation</span> ; <span>chimioprophylaxie</span> antipaludique suivie ou non ; statut vaccinal ; activités à risque (baignade, <span>contact</span> animal, rapports)</td>\n          </tr>\n          <tr>\n            <td><strong>Réflexe n°1</strong></td>\n            <td>Éliminer en <span>urgence</span> un <span><span class=\"nc-red_bg\">paludisme à </span><em><span class=\"nc-red_bg\">P. falciparum</span></em></span> : <span>frottis-goutte épaisse</span> + <span>TDR</span> sans délai — <span>urgence</span> diagnostique <strong>et</strong> thérapeutique</td>\n          </tr>\n          <tr>\n            <td><strong>Bilan <span>biologique</span></strong></td>\n            <td><span>NFS</span> ; <span>CRP</span> ; <span>transaminases</span> ; <span>hémocultures</span> ; <span>sérologies</span> orientées par la clinique</td>\n          </tr>\n          <tr>\n            <td><strong>Élargir</strong></td>\n            <td>Penser aux causes <strong>non infectieuses</strong> (MTEV, néoplasie, maladie <span>inflammatoire</span>) et infectieuses <strong>cosmopolites</strong> (PNA, <span>grippe</span>, pneumopathie)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Règle absolue.</strong> Toute <span><span class=\"nc-blue_bg\">fièvre</span></span> au retour des tropiques est un <span>paludisme jusqu'à preuve du contraire</span> — le frottis-<span>goutte épaisse</span> prime sur tout autre examen.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span>Paludisme</span> · 190 — <span>Fièvre</span> prolongée</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":2},{"id":"175-10","rang":"B","rubrique":"Étiologies","titre":"Connaître les signes d’orientation étiologiques en fonction des durées d’incubation","contenu":"<div class=\"notion-course\"><p>La <strong>durée d'incubation</strong> (intervalle entre l'exposition et l'apparition de la <span>fièvre</span>) restreint fortement le champ étiologique.</p>\n      <table>\n        <thead><tr><th>Incubation</th><th>Étiologies à évoquer</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>&lt;<span> 7 jours</span></strong></td>\n            <td><strong><span class=\"nc-orange_bg\">Diarrhées infectieuses</span> :</strong> <span class=\"nc-purple_bg\">shigellose</span> ; choléra ; <span class=\"nc-purple_bg\">salmonelloses</span> non typhiques<br><strong>Arboviroses :</strong> dengue ; zika ; chikungunya</td>\n          </tr>\n          <tr>\n            <td><strong><span>7-14 jours</span></strong></td>\n            <td><span><span class=\"nc-red_bg\">Paludisme à </span><em><span class=\"nc-red_bg\">P. falciparum</span></em></span> ; <span><span class=\"nc-red_bg\">typhoïde</span></span> ; spirochétoses (<span class=\"nc-purple_bg\">leptospirose</span>, <span class=\"nc-purple_bg\">borrélioses</span>) ; <span class=\"nc-purple_bg\">rickettsioses</span></td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span> 2 semaines</span></strong></td>\n            <td><span><span class=\"nc-red_bg\">Paludisme</span></span><span class=\"nc-red_bg\"> à </span><em><span><span class=\"nc-red_bg\">P. falciparum</span></span></em> (jusqu'à<span> <span class=\"nc-pink nc-bold\">2 mois</span></span>) ; <span class=\"nc-red_bg\">typhoïde</span> (jusqu'à<span> <span class=\"nc-pink nc-bold\">3 semaines</span></span>) ; hépatites A, B et E ; <span><span class=\"nc-green_bg\">primo-infection VIH</span></span> (<span>2-8 semaines</span>) ; <span class=\"nc-orange_bg\">schistosomose en phase d'invasion</span> (<span>2-6 semaines</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Mois à années</strong></td>\n            <td><span class=\"nc-purple_bg\">Trypanosomoses</span> ; <span class=\"nc-purple_bg\">leishmaniose viscérale</span> ; <span><span class=\"nc-orange nc-bold\">paludisme</span></span> à <em>P. non falciparum</em> ; <span><span class=\"nc-red nc-bold\">amoebose hépatique</span></span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> L'<span class=\"nc-green nc-bold\">amoebose intestinale aiguë ne donne </span><strong><span class=\"nc-green nc-bold\">pas</span></strong><span class=\"nc-green nc-bold\"> de </span><span><span class=\"nc-green nc-bold\">fièvre</span></span> — seule l'<span class=\"nc-red nc-bold\">amoebose </span><strong><span class=\"nc-red nc-bold\">hépatique</span></strong> est fébrile.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"175-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités d’analyse de la courbe thermique en cas de fièvre au retour du voyage","contenu":"<div class=\"notion-course\"><p>L'<strong>allure de la courbe thermique</strong> et <span>les</span> signes cliniques associés affinent l'orientation étiologique.</p>\n      <table>\n        <thead><tr><th>Profil thermique</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Fièvre</span> récurrente</strong> (accès fébriles répétés)</td><td><span><span class=\"nc-orange_bg\">Paludisme</span></span> ; <span><span class=\"nc-purple_bg\">borréliose</span></span></td></tr>\n          <tr><td><strong><span><span class=\"nc-blue_bg\">Fièvre</span></span> <span class=\"nc-yellow_bg nc-bold\">en plateau</span></strong></td><td><span>Typhoïde</span> au 3ᵉ septénaire ; <span class=\"nc-green_bg\">viroses</span> (dengue, chikungunya, <span><span class=\"nc-green_bg\">primo-infection</span></span><span class=\"nc-green_bg\"> </span><span><span class=\"nc-green_bg\">VIH</span></span>) ; <span class=\"nc-orange_bg\">schistosomose</span></td></tr>\n          <tr><td><strong><span>Fièvre</span> + signes hémorragiques</strong></td><td><span><span class=\"nc-orange_bg\">Paludisme</span></span> ; <span><span class=\"nc-green_bg\">hépatite</span></span><span class=\"nc-green_bg\"> fulminante</span> ; <span class=\"nc-purple_bg\">leptospirose ictéro-</span><span><span class=\"nc-purple_bg\">hémorragique</span></span> ; dengue et <span class=\"nc-green_bg\">arboviroses</span> hémorragiques ; <span>fièvres hémorragiques virales</span></td></tr>\n        </tbody>\n      </table>\n      <p><span>Les</span> <strong>signes cliniques associés</strong> orientent également :</p>\n      <ul>\n        <li><strong><span>Ictère</span> :</strong> <span>hépatite</span> aiguë ; <span><span class=\"nc-orange_bg\">paludisme</span></span> ; <span class=\"nc-purple_bg\">leptospirose</span></li>\n        <li><strong><span>Hépatomégalie</span> :</strong> <span class=\"nc-red_bg\">typhoïde</span> ; <span>hépatite</span> aiguë ; <span><span class=\"nc-red nc-bold\">paludisme</span></span> ; amoebose ; <span class=\"nc-orange_bg\">schistosomose</span></li>\n        <li><strong><span>Splénomégalie</span> :</strong> <span>paludisme</span> ; brucellose ; <span class=\"nc-red_bg\">typhoïde</span> ; <span class=\"nc-pink nc-bold\">dengue</span></li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":1},{"id":"175-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic d’une fièvre hémorragique virale","contenu":"<div class=\"notion-course\"><p><span>Les</span> <span>fièvres hémorragiques virales (FHV)</span> sont rares mais d'une gravité extrême et hautement contagieuses.</p>\n      <ul>\n        <li><strong>Virus :</strong> <span><span class=\"nc-red nc-bold\">Ebola</span></span>, <span><span class=\"nc-red nc-bold\">Marburg</span></span>, <span><span class=\"nc-red nc-bold\">Lassa</span></span> — ce ne sont <strong>pas</strong> des arboviroses</li>\n        <li><strong>Présentation :</strong> <span><span class=\"nc-blue_bg\">fièvre</span></span> associée à un <span>syndrome hémorragique</span> au retour d'une zone à risque</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Conduite à tenir.</strong> Toute suspicion de FHV impose des <span>précautions complémentaires</span> renforcées pour la protection du patient <strong>et</strong> du personnel : <span>isolement</span> et <span>signalement</span> immédiats. La prise en charge est guidée par le <span><span class=\"nc-blue nc-bold\">Centre National de Référence</span> (CNR) des fièvres hémorragiques virales</span> et <span>Santé publique France</span> — <span>les</span> contacter avant tout prélèvement.</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les fièvres hémorragiques virales n’ont pas toutes le même vecteur ni la même contagiosité. L’absence de saignement n’élimine pas une infection à risque ; l’exposition géographique et clinique déclenche l’alerte, l’isolement adapté et l’avis spécialisé avant les prélèvements usuels.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"175-13","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de la typhoïde","contenu":"<div class=\"notion-course\"><p>La <span>fièvre <span class=\"nc-red nc-bold\">typhoïde</span></span> est une infection systémique à transmission oro-fécale, à <strong><span class=\"nc-yellow_bg\">déclaration obl</span><span><span class=\"nc-yellow_bg\">iga</span></span><span class=\"nc-yellow_bg\">toire</span></strong>.</p>\n      <table>\n        <thead><tr><th>Item</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Germe</strong></td><td><span><span class=\"nc-purple_bg\">Salmonella</span> <span class=\"nc-purple_bg\">enterica</span></span> sérotypes <span class=\"nc-purple_bg\">Typhi</span> et <span class=\"nc-purple_bg\">Paratyphi A, B ou C</span> ; <strong>réservoir <span class=\"nc-yellow_bg nc-bold\">strictement humain</span></strong></td></tr>\n          <tr><td><strong><span>Physiopathologie</span></strong></td><td>Franchissement de la barrière intestinale <span class=\"nc-green_bg\">sans la léser</span> → circulation sanguine via le <span class=\"nc-purple_bg\">système lymphatique</span> → lyse <span>bactérienne</span> libérant une <span><span class=\"nc-pink nc-bold\">endotoxine</span></span> responsable des manifestations viscérales</td></tr>\n          <tr><td><strong>Incubation</strong></td><td><span>10 jours à 3 semaines</span></td></tr>\n          <tr><td><strong>Phase d'invasion</strong> (<span>1 semaine</span>)</td><td><span><span class=\"nc-blue_bg\">Fièvre</span></span><span class=\"nc-blue_bg\"> progressivement croissante</span> ; <span>asthénie</span>, <span>anorexie</span>, <span>céphalées</span>, insomnie ; <span><span class=\"nc-yellow_bg\">pouls dissocié</span></span> ; <span><span class=\"nc-blue_bg\">splénomégalie</span></span> (<span>30 %</span>) ; <span class=\"nc-blue_bg\">troubles digestifs</span></td></tr>\n          <tr><td><strong>Phase d'état</strong></td><td><span><span class=\"nc-yellow_bg\">Fièvre</span></span> <span><span class=\"nc-yellow_bg nc-bold\">en plateau</span></span> <span class=\"nc-yellow_bg\">à</span><span><span class=\"nc-yellow_bg\"> 40 °C</span></span> ; <span class=\"nc-yellow_bg\">pouls dissocié</span> ; <span><span class=\"nc-yellow_bg\">tuphos</span></span> (inversion du rythme nycthéméral, prostration, <span>obnubilation</span>) ; <span>diarrhée « <span class=\"nc-blue_bg nc-bold\">jus de melon</span> »</span> (2/3 des cas) ; exanthème lenticulaire roséoliforme du tronc (1/3) ; <span><span class=\"nc-orange_bg\">angine de Duguet</span></span> (ulcérations des <span class=\"nc-blue nc-bold\">piliers antérieurs</span> et du <span class=\"nc-blue nc-bold\">voile du palais</span>,<span> 10 %</span>)</td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span><span class=\"nc-blue_bg\">Leuco-neutropénie</span></span> ; <span><span class=\"nc-blue_bg\">CRP élevée</span></span></td></tr>\n          <tr><td><strong>Confirmation</strong></td><td><span>Hémocultures</span></td></tr>\n          <tr><td><strong>Complications</strong></td><td><strong><span class=\"nc-red nc-bold\">Digestives</span> :</strong> <span><span class=\"nc-red nc-bold\">hémorragies</span> <span class=\"nc-red nc-bold\">digestives</span></span> ; <span>perforations digestives</span><br><strong>Toxiniques :</strong> <span class=\"nc-red nc-bold\">myocardite</span> ; <span>encéphalite</span><br><strong>Septiques :</strong> <span class=\"nc-red_bg\">localisations septiques secondaires</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> La <span><span class=\"nc-yellow_bg\">fièvre</span></span> typhoïde est une <strong>maladie à <span class=\"nc-yellow_bg\">déclaration obl</span><span><span class=\"nc-yellow_bg\">iga</span></span><span class=\"nc-yellow_bg\">toire</span></strong> ; le traitement repose sur une C<span <span=\"\">&gt;3</span>G parentérale en probabiliste, secondairement adaptée à l'<span>antibiogramme</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"175-14","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des diarrhées d’importation","contenu":"<div class=\"notion-course\"><p><span>Les</span> diarrhées d'importation se classent selon la présence ou non de <strong><span>fièvre</span></strong>.</p>\n      <table>\n        <thead><tr><th>Type</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-red nc-bold\">Diarrhée</span></span> fébrile</strong> (souvent aiguë)</td>\n            <td><span><span class=\"nc-brown_bg\">Turista</span></span> ; <span><span class=\"nc-red_bg\">paludisme</span></span> (à évoquer en premier, surtout chez l'enfant) ; <span class=\"nc-purple_bg\">shigellose</span>, <span class=\"nc-purple_bg\">salmonelloses</span>, <em><span><span class=\"nc-purple_bg\">Campylobacter</span></span></em> si <span>syndrome dysentérique</span> (<span>coproculture</span>) ; <span><span class=\"nc-green_bg\">primo-infection VIH</span></span> ; hépatites A et E ; <em><span class=\"nc-purple_bg\">Clostridioides difficile</span></em> en cas d'ATB récente</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-red nc-bold\">Diarrhée</span></span> non fébrile</strong> (souvent subaiguë)</td>\n            <td><span><span class=\"nc-red nc-bold\">Paludisme</span></span> (<span>10 %</span> de présentations atypiques) ; <span><span class=\"nc-purple_bg\">choléra</span></span> ; <span class=\"nc-orange_bg\">helminthoses intestinales</span> (orientées par l'<span>hyperéosinophilie</span>) ; <span>protozooses</span> le plus souvent : <span><span class=\"nc-red nc-bold\">giardose</span></span> (cause la plus fréquente de <span><span class=\"nc-red nc-bold\">diarrhée</span></span> prolongée non fébrile au retour des tropiques), <span class=\"nc-red nc-bold\">amoebose intestinale aiguë</span>, <span class=\"nc-red nc-bold\">cyclosporose</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Diarrhée</span> médicamenteuse</strong></td>\n            <td><span>AINS</span> ; antipaludiques (<span><span class=\"nc-pink_bg\">atovaquone-proguanil</span></span>, chloroquine-proguanil)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pièges.</strong> Le <span><span class=\"nc-red nc-bold\">paludisme</span></span> peut se présenter comme une <span><span class=\"nc-red nc-bold\">diarrhée</span></span> <strong>non fébrile</strong> atypique. L'<span class=\"nc-green nc-bold\">amoebose intestinale aiguë ne donne </span><strong><span class=\"nc-green nc-bold\">pas</span></strong><span class=\"nc-green nc-bold\"> de </span><span><span class=\"nc-green nc-bold\">fièvre</span></span>, alors que l'<span class=\"nc-red nc-bold\">amoebose </span><strong><span class=\"nc-red nc-bold\">hépatique</span></strong><span class=\"nc-red nc-bold\"> peut donner des diarrhées fébriles</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 176 — <span>Diarrhée</span> infectieuse · 286 — <span>Diarrhée</span> aiguë - <span>déshydratation</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"175-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","contenu":"<div class=\"notion-course\"><p>La <span>diarrhée du voyageur (turista)</span> est extrêmement fréquente mais rarement grave.</p>\n      <table>\n        <thead><tr><th>Item</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Délai</strong></td><td>Survient souvent la <span>1ʳᵉ semaine</span> du séjour ; guérison spontanée en <span>3-5 jours</span></td></tr>\n          <tr>\n            <td><strong>Germes</strong></td>\n            <td><strong>Bactéries (<span>50 %</span>) :</strong> <span>E. coli entérotoxinogène (ETEC)</span> au 1ᵉʳ plan ; <span><span class=\"nc-purple_bg\">E. coli</span></span><span class=\"nc-purple_bg\"> entéro-invasif</span> ; <span>Salmonella</span><br><strong>Virus (<span>5-25 %</span>) :</strong> <span>norovirus</span><br><strong>Parasites (&lt;<span> 10 %</span>) :</strong> protozoaires, <span class=\"nc-purple_bg\">amibes</span></td>\n          </tr>\n          <tr><td><strong>Prise en charge</strong></td><td><span><span class=\"nc-green_bg\">Réhydratation</span></span><span class=\"nc-green_bg\"> dans tous </span><span><span class=\"nc-green_bg\">les</span></span><span class=\"nc-green_bg\"> cas</span> (<span class=\"nc-green_bg\">SRO</span> chez l'enfant) ; <span><span class=\"nc-pink_bg\">racécadotril</span></span> (<span class=\"nc-pink_bg\">antidiarrhéique antisécrétoire</span>) si nécessaire ; <span>antibiothérapie</span> <strong>non recommandée en routine</strong></td></tr>\n          <tr><td><strong>Indications d'ATB</strong></td><td><span><span class=\"nc-pink_bg\">Azithromycine</span></span> en 1ʳᵉ intention (ou <span>ciprofloxacine</span>), <span><span class=\"nc-pink nc-bold\">1 à 5 jours</span></span> — uniquement si <span><span class=\"nc-red_bg\">diarrhée</span></span><span class=\"nc-red_bg\"> invasive</span>, ou <span>diarrhée</span> cholériforme intense persistant <span>&gt; 48 h</span> sans recours possible aux soins locaux</td></tr>\n        </tbody>\n      </table>\n      <p>Devant une suspicion de <strong><span class=\"nc-orange_bg\">protozoose</span></strong> (<span>diarrhée</span> prolongée) :</p>\n      <ol>\n        <li><span><span class=\"nc-blue\">Examen parasitologique des selles</span></span></li>\n        <li>Si difficile : <span>traitement d'épreuve</span> par nitro-imidazolé (<span><span class=\"nc-pink\">métronidazole</span></span>)</li>\n        <li>Si échec : <span><span class=\"nc-blue\">coloscopie</span></span> parfois nécessaire</li>\n      </ol>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 176 — <span>Diarrhée</span> infectieuse · 285 — <span>Diarrhée</span> chronique</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":1},{"id":"175-16","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir évoquer puis confirmer le diagnostic des parasitoses intestinales","contenu":"<div class=\"notion-course\"><p>Le diagnostic des <span class=\"nc-red nc-bold\">parasitoses intestinales</span> suit deux temps : <strong>évoquer</strong>, puis <strong>confirmer</strong>.</p>\n      <p><strong>Évoquer</strong> devant :</p>\n      <ul>\n        <li>Une <span>diarrhée prolongée non fébrile</span> au retour des tropiques (<span><span class=\"nc-red nc-bold\">giardose</span></span> ++)</li>\n        <li>Une <span>hyperéosinophilie</span> sanguine → oriente vers une <span>helminthose</span></li>\n        <li>Un contexte d'exposition (baignade en eau douce → <span>schistosomose</span>)</li>\n      </ul>\n      <p><strong>Confirmer</strong> par :</p>\n      <ul>\n        <li><span><span class=\"nc-blue\">Examen parasitologique des selles</span></span> (à répéter) — recherche de kystes, œufs ou larves</li>\n        <li><span><span class=\"nc-blue_bg\">Sérologie</span></span>, utile notamment en phase précoce</li>\n        <li>Si les examens sont négatifs mais la suspicion persistante : compléter ou répéter les prélèvements et demander un avis. Le <span class=\"nc-pink\">métronidazole</span> ne couvre pas toutes les parasitoses et n’est pas un traitement automatique de toute diarrhée inexpliquée.</li>\n        <li><span>Endoscopie</span> (rectos<span>igm</span>oïdoscopie) en dernier recours</li>\n      </ul>\n      <p>Principales <span>protozooses</span> intestinales : <span><span class=\"nc-red nc-bold\">giardose</span></span>, <span>amoebose à <em>Entamoeba histolytica</em></span>, <span><span class=\"nc-red nc-bold\">cyclosporose</span></span> — traitement par <span><span class=\"nc-pink\">métronidazole</span></span> pour l'amoebose.</p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"175-17","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription des recherches parasitologiques dans des contextes évocateurs (schistosomoses, helminthoses digestives, protozooses digestives)","contenu":"<div class=\"notion-course\"><p><span>Les</span> recherches parasitologiques se prescrivent dans un <strong>contexte évocateur</strong> (exposition, symptômes, hyperéosinophilie) et selon le parasite suspecté.</p>\n      <table>\n        <thead><tr><th>Contexte</th><th>Modalités de prescription</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-purple_bg\">Schistosomoses</span></span></strong></td>\n            <td><strong>Phase d'invasion :</strong> <span>sérologie</span><br><strong>Phase d'état :</strong> recherche d'œufs par microscopie ou <span><span class=\"nc-blue nc-bold\">TAAN</span></span> sur <span><span class=\"nc-blue nc-bold\">urines 3 jours de suite</span></span>, <span><span class=\"nc-blue nc-bold\">selles</span></span>, et <span><span class=\"nc-blue nc-bold\">biopsies par voie endoscopique</span></span> (vessie, rectum)</td>\n          </tr>\n          <tr>\n            <td><strong>Helminthoses digestives</strong></td>\n            <td><span><span class=\"nc-blue\">Examen parasitologique des selles</span></span> ; recherche d'une <span>hyperéosinophilie</span> sanguine d'orientation</td>\n          </tr>\n          <tr>\n            <td><strong>Protozooses digestives</strong></td>\n            <td><span><span class=\"nc-blue\">Examen parasitologique des selles</span></span> répété (<span class=\"nc-red nc-bold\">giardose</span>, amoebose, <span class=\"nc-red nc-bold\">cyclosporose</span>) ; <span>TAAN</span> dans certains cas</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 218 — Eosinophilie</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"175-18","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique en cas de lésion cutanée au retour du voyage","contenu":"<div class=\"notion-course\"><p>Devant une <strong><span>lésion</span> cutanée au retour d'un voyage</strong>, le type de lésion élémentaire oriente le diagnostic.</p>\n      <table>\n        <thead><tr><th>Type de lésion</th><th>Étiologies à évoquer</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Exanthème fébrile</span></strong></td><td><span><span class=\"nc-green_bg\">Primo-infection VIH</span></span> ; <span class=\"nc-green_bg\">arboviroses</span> (dengue, chikungunya, zika) ; <span class=\"nc-purple_bg\">rickettsiose</span> ; <span class=\"nc-purple_bg\">leptospirose</span> ; <span>allergie</span> médicamenteuse</td></tr>\n          <tr><td><strong><span><span class=\"nc-yellow_bg\">Escarre d'inoculation</span></span></strong></td><td><span>Rickettsiose</span></td></tr>\n          <tr><td><strong><span>Lésions urticariennes</span></strong></td><td><span><span class=\"nc-orange_bg\">Schistosomose</span></span><span class=\"nc-orange_bg\"> en phase d'invasion</span> ; <span>hépatite</span> <span>virale</span> en phase pré-ictérique ; <span>allergie</span> médicamenteuse</td></tr>\n          <tr><td><strong>Maladies tropicales localisées à la peau</strong></td><td><span><span class=\"nc-orange_bg\">Leishmaniose cutanée</span></span> (<span>ulcération</span> d'<span>évolution</span> chronique, lésion nodulaire) ; <span><span class=\"nc-orange_bg\">larva migrans cutanée</span></span><span class=\"nc-orange_bg\"> ankylostomienne</span> ; <span><span class=\"nc-orange_bg\">myiase</span></span> (nodules non nécrotiques) ; <span><span class=\"nc-blue_bg\">prurigo</span></span><span class=\"nc-blue_bg\"> après piqûre d'insecte</span></td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":4},{"id":"175-19","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales dermatoses d’importation","contenu":"<div class=\"notion-course\"><p><span>Les</span> <strong>dermatoses d'importation</strong> se reconnaissent au type de <span>lésion</span> élémentaire.</p>\n      <table>\n        <thead><tr><th>Lésion</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Œdème</span></strong></td><td><strong>Membres :</strong> <span>dermohypodermite bactérienne</span> (<span>streptocoque</span> du groupe A, <em>S. aureus</em>) ; <span>loase</span> ; filarioses lymphatiques<br><strong>Face :</strong> <span>trichinellose</span> ; <span>maladie de Chagas</span></td></tr>\n          <tr><td><strong>Nodules</strong></td><td><strong>Nécrotiques :</strong> <span>furoncle</span> (<em>S. aureus</em>)<br><strong>Non nécrotiques :</strong> <span><span class=\"nc-orange_bg\">myiase</span></span> ; <span>tungose</span> (puces-chiques)</td></tr>\n          <tr><td><strong><span>Ulcération</span></strong></td><td>Ecthyma (<span>streptocoque</span> A, <em>S. aureus</em>) ; <span>charbon</span> ; trypanosome ; <span>ulcère de Buruli</span> ; <span>leishmaniose</span> (<span>évolution</span> chronique)</td></tr>\n          <tr><td><strong><span>Lésion</span> nodulaire</strong></td><td><span>Leishmaniose</span> ; <span>mycobactéries atypiques</span> ; <span>sporotrichose</span></td></tr>\n          <tr><td><strong>Exanthème</strong></td><td><strong>Urticarien :</strong> invasions helminthiques (<span class=\"nc-orange_bg\">schistosomose</span>, <span>syndrome de Löffler</span>), filariose, <span>primo-infection</span> <span>VIH</span><br><strong>Maculopapuleux :</strong> arboviroses ; <span class=\"nc-green_bg\">primo-infection VIH</span> ; <span class=\"nc-orange_bg\">rickettsioses</span> ; <span>syphilis</span></td></tr>\n          <tr><td><strong><span><span class=\"nc-blue_bg\">Prurit</span></span> diffus</strong></td><td><span>Gale</span> ; piqûres d'arthropodes ; <span><span class=\"nc-green_bg\">primo-infection</span></span><span class=\"nc-green_bg\"> </span><span><span class=\"nc-green_bg\">VIH</span></span> ; <span>onchocercose</span> ; <span><span class=\"nc-blue_bg\">dermatite</span></span> des nageurs</td></tr>\n          <tr><td><strong><span>Larva migrans cutanée</span></strong></td><td>Larbish (ankylostomes du chien ou du chat) ; larva currens (<span>strongyloïdose</span> ; Asie du Sud-Est, Mexique)</td></tr>\n        </tbody>\n      </table>\n      <p>Quelques dermatoses d'importation typiques :</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/175/dengue-exantheme.png\" alt=\"Exanthème maculeux diffus de l&#x27;abdomen au cours d&#x27;une dengue\" loading=\"lazy\">\n        <figcaption>Dengue — exanthème maculeux diffus, signe cutané fréquent des arboviroses fébriles. Source : fiche source EDN item 175 — Voyage en pays tropical (Pilly étudiant 2023).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/175/larva-migrans-pied.png\" alt=\"Larva migrans cutanée de la plante du pied — cordon serpigineux érythémateux\" loading=\"lazy\">\n        <figcaption>Larva migrans cutanée du pied chez un enfant de <span>9 ans</span> (Brésil) — cordon serpigineux prurigineux dû à la migration sous-cutanée d'une larve d'ankylostome. Source : fiche source EDN item 175 — Voyage en pays tropical (Pilly étudiant 2023).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/175/myiase-extraction.png\" alt=\"Larve de Dermatobia hominis après extraction d&#x27;un nodule cutané de myiase\" loading=\"lazy\">\n        <figcaption>Myiase à <em>Dermatobia hominis</em> — larve après extraction du <span>nodule</span> cutané. Source : fiche source EDN item 175 — Voyage en pays tropical (Pilly étudiant 2023).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/175/myiase-nodule.png\" alt=\"Lésion nodulaire pseudo-pustuleuse d&#x27;une myiase cutanée\" loading=\"lazy\">\n        <figcaption>Myiase — <span>lésion</span> nodulaire pseudo-pustuleuse, non nécrotique. Source : fiche source EDN item 175 — Voyage en pays tropical (Pilly étudiant 2023).</figcaption>\n      </figure></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 175</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">Paludisme</span> à <em><span class=\"kw-clinique\">P. falciparum</span></em> — réflexe n°1</strong></p><p><span class=\"kw-bio\">frottis mince</span> + <span class=\"kw-bio\">goutte épaisse</span> + <span class=\"kw-bio\">TDR</span> <strong>sans délai</strong> — <span class=\"kw-alerte\">urgence diagnostique ET thérapeutique</span> (cf. item 170)</p><ul><li>1ʳᵉ cause à évoquer devant toute <span class=\"kw-clinique\">fièvre</span> survenant dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> suivant le retour d’une zone d’endémie</li></ul><p><strong><span class=\"kw-etio\">Fièvre hémorragique virale</span> suspectée</strong></p><p><span class=\"kw-alerte\">isolement et signalement immédiats</span> ; <span class=\"kw-ttt\">précautions complémentaires</span> renforcées (patient ET personnel) ; contacter le <span class=\"kw-def\">CNR des fièvres hémorragiques virales</span> et <span class=\"kw-def\">Santé publique France</span> <strong>avant tout prélèvement</strong></p><p><strong><span class=\"kw-etio\">Dengue</span> — fenêtre <span class=\"kw-bio\">PCR</span></strong></p><p><span class=\"kw-bio\">PCR</span> positive uniquement durant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 premiers jours</span> de <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-bio\">sérologie</span> au-delà</p><p><strong>Exposition sexuelle à risque</strong></p><p>consulter au plus tôt (<span class=\"kw-chiffre\">&lt; 24 h</span>) pour un éventuel <span class=\"kw-ttt\">traitement post-exposition</span></p>","hospit":"<p><strong><span class=\"kw-clinique\">Paludisme</span> à <em><span class=\"kw-clinique\">P. falciparum</span></em> confirmé :</strong> prise en charge en <span class=\"kw-alerte\">urgence</span> diagnostique et thérapeutique ; recherche des <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> et traitement spécifique — <em>cf. item 170 (Paludisme)</em>.</p><p><strong><span class=\"kw-etio\">Fièvre hémorragique virale</span> suspectée :</strong> <span class=\"kw-alerte\">isolement immédiat</span> et <span class=\"kw-ttt\">précautions complémentaires</span>, orientation guidée par le <span class=\"kw-def\">CNR</span> et <span class=\"kw-def\">Santé publique France</span>.</p><p><strong><span class=\"kw-etio\">Fièvre typhoïde</span> :</strong> infection systémique relevant d’une <span class=\"kw-ttt\">antibiothérapie parentérale</span> (<span class=\"kw-ttt\">C3G</span>) ; <span class=\"kw-alerte\">maladie à déclaration obligatoire</span>.</p><p><strong><span class=\"kw-etio\">Turista</span> :</strong> prise en charge <span class=\"kw-clinique\">ambulatoire</span> (rarement grave), centrée sur la <span class=\"kw-ttt\">réhydratation</span> ; <span class=\"kw-alerte\">hospitalisation</span> réservée aux formes sévères ou au <span class=\"kw-def\">terrain</span> fragile.</p>","redflags":"<ul><li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-alerte\">signes hémorragiques</span> → évoquer <span class=\"kw-etio\">fièvre hémorragique virale</span> (<span class=\"kw-etio\">Ebola</span>, <span class=\"kw-etio\">Marburg</span>, <span class=\"kw-etio\">Lassa</span>), <span class=\"kw-etio\">paludisme</span>, <span class=\"kw-etio\">dengue</span> <span class=\"kw-etio\">hémorragique</span>, <span class=\"kw-etio\">leptospirose</span> ictéro-hémorragique, <span class=\"kw-etio\">hépatite</span> fulminante, <span class=\"kw-etio\">fièvre jaune</span></li><li><span class=\"kw-etio\">Fièvre jaune</span> : <span class=\"kw-alerte\">insuffisance hépatocellulaire et rénale</span> avec <span class=\"kw-alerte\">syndrome hémorragique</span> — <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">20 %</span></li><li><span class=\"kw-etio\">Arbovirose</span> se compliquant d’<span class=\"kw-alerte\">hémorragies</span> et/ou d’<span class=\"kw-alerte\">encéphalite</span></li><li><span class=\"kw-etio\">Dengue</span> <span class=\"kw-etio\">hémorragique</span> / <span class=\"kw-alerte\">choc</span> (1 cas / 1 000)</li><li><span class=\"kw-etio\">Fièvre typhoïde</span> compliquée : <span class=\"kw-alerte\">hémorragies digestives</span>, <span class=\"kw-alerte\">perforations digestives</span>, <span class=\"kw-alerte\">myocardite</span>, <span class=\"kw-alerte\">encéphalite</span></li><li><span class=\"kw-clinique\">Ictère</span> fébrile → <span class=\"kw-etio\">hépatite</span> aiguë, <span class=\"kw-etio\">paludisme</span>, <span class=\"kw-etio\">leptospirose</span></li><li><span class=\"kw-def\">Terrain</span> à risque de forme grave : <span class=\"kw-alerte\">immunodéprimé</span>, <span class=\"kw-alerte\">femme enceinte</span>, <span class=\"kw-alerte\">jeune enfant</span> (<span class=\"kw-etio\">paludisme</span> à évoquer en 1ᵉʳ)</li></ul>","principes":"<p>Après élimination du <span class=\"kw-etio\">paludisme</span>, la prise en charge est <strong>étiologique</strong> : <span class=\"kw-ttt\">réhydratation</span> de la <span class=\"kw-etio\">turista</span>, <span class=\"kw-ttt\">antibiothérapie</span> ciblée des bactérioses (typhoïde), <span class=\"kw-ttt\">antiparasitaires</span> (schistosomose, amoebose, protozooses), traitement <strong>symptomatique</strong> des arboviroses.</p><p><strong><span class=\"kw-etio\">Turista</span> (<span class=\"kw-clinique\">diarrhée</span> du voyageur)</strong></p><ul><li><span class=\"kw-ttt\">Réhydratation</span> dans tous <span class=\"kw-clinique\">les</span> cas (<span class=\"kw-ttt\">SRO</span> chez l’enfant)</li><li><span class=\"kw-ttt\">Racécadotril</span> (antidiarrhéique antisécrétoire) si nécessaire</li><li><span class=\"kw-ttt\">Antibiothérapie</span> <strong>non recommandée en routine</strong></li><li><span class=\"kw-ttt\">Azithromycine</span> en 1ʳᵉ intention (ou <span class=\"kw-ttt\">ciprofloxacine</span>), <span class=\"kw-chiffre\">1 à 5 jours</span> — uniquement si <span class=\"kw-clinique\">diarrhée</span> invasive, ou cholériforme intense persistant <span class=\"kw-chiffre\">&gt; 48 h</span> sans recours possible aux soins locaux</li></ul><p><strong><span class=\"kw-clinique\">Diarrhée</span> prolongée / <span class=\"kw-etio\">protozoose</span></strong></p><ul><li>1. <span class=\"kw-bio\">Examen parasitologique des selles</span></li><li>2. Si difficile : <span class=\"kw-ttt\">traitement d’épreuve</span> par nitro-imidazolé (<span class=\"kw-ttt\">métronidazole</span>)</li><li>3. Si échec : <span class=\"kw-imagerie\">coloscopie</span> parfois nécessaire</li></ul><p><strong><span class=\"kw-etio\">Fièvre typhoïde</span></strong></p><ul><li><span class=\"kw-ttt\">C3G parentérale</span> en probabiliste, puis adaptation à l’<span class=\"kw-bio\">antibiogramme</span> (<span class=\"kw-ttt\">fluoroquinolone</span>, <span class=\"kw-ttt\">C3G parentérale</span> ou <span class=\"kw-ttt\">azithromycine</span>) ; <span class=\"kw-alerte\">déclaration obligatoire</span></li></ul><p><strong><span class=\"kw-etio\">Schistosomose</span></strong></p><ul><li><span class=\"kw-ttt\">Praziquantel</span></li></ul><p><strong><span class=\"kw-etio\">Amoebose hépatique</span></strong></p><ul><li><span class=\"kw-ttt\">Métronidazole</span> (nitro-imidazolé)</li></ul><p><strong><span class=\"kw-etio\">Arboviroses</span> (dengue, chikungunya, zika)</strong></p><ul><li>Traitement <strong>uniquement symptomatique</strong></li></ul>","suivi":"<p><strong>Déclaration obl<span class=\"kw-chiffre\">iga</span>toire :</strong> <span class=\"kw-etio\">fièvre typhoïde</span> ; <span class=\"kw-etio\">dengue</span> et <span class=\"kw-etio\">chikungunya</span> diagnostiqués en France métropolitaine (<span class=\"kw-def\">surveillance</span> des cas autochtones, vecteur <em>Aedes</em> répandu de <span class=\"kw-chiffre\">mai à octobre</span> dans le Sud-Est).</p><p><strong><span class=\"kw-etio\">Fièvre hémorragique virale</span> :</strong> <span class=\"kw-def\">signalement</span> et <span class=\"kw-def\">suivi</span> guidés par le <span class=\"kw-def\">CNR des fièvres hémorragiques virales</span> et <span class=\"kw-def\">Santé publique France</span>.</p><p><strong><span class=\"kw-etio\">Turista</span> :</strong> guérison spontanée en <span class=\"kw-chiffre\">3-5 jours</span> ; surveiller l’hydratation (<span class=\"kw-ttt\">SRO</span> chez l’enfant).</p><p><strong><span class=\"kw-etio\">Schistosomose</span> (phase d’état) :</strong> recherche d’œufs sur <span class=\"kw-clinique\">urines 3 jours de suite</span>, <span class=\"kw-clinique\">selles</span> et <span class=\"kw-clinique\">biopsies endoscopiques</span> (vessie, rectum).</p><p><strong><span class=\"kw-etio\">Paludisme</span> :</strong> surveillance parasitologique et clinique — <em>cf. item 170</em>.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf","label":"Collège Pilly — Voyage pays tropical (item 175, PDF)"},{"href":"https://www.hypocampus.fr/home/#/book/5525/chaptergroup/914279?chapter=48474","label":"Hypocampus — Voyage tropical"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Fièvre au retour des tropiques — Réflexe n°1 : frottis + goutte épaisse + TDR sans délai — toute fièvre = paludisme à P. falciparum jusqu’à preuve du contraire","detail":"<h4>CAT — <span class=\"kw-clinique\">Fièvre</span> au retour des tropiques — Démarche diagnostique : éliminer en <span class=\"kw-alerte\">urgence</span> un <span class=\"kw-clinique\">paludisme</span> à P. falciparum</h4>","branches":[{"to":"t-palu","label":"Frottis-GE / TDR POSITIF","color":"red"},{"to":"q-syndrome","label":"Frottis-GE / TDR NÉGATIF — orienter selon le syndrome","color":"amber"}]},{"id":"t-palu","kind":"terminal","label":"Paludisme à P. falciparum","color":"red","detail":"<h4>Clinique</h4><ul><li>Troubles <span class=\"kw-clinique\">digestifs</span> et <span class=\"kw-clinique\">neurologiques</span> ; <span class=\"kw-clinique\">splénomégalie</span>, <span class=\"kw-clinique\">hépatomégalie</span> ; contamination par l’<span class=\"kw-etio\">anophèle</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Thrombopénie</span> ++, <span class=\"kw-bio\">anémie</span>, <span class=\"kw-bio\">leucopénie</span> ; <span class=\"kw-bio\">CRP</span> élevée ; <span class=\"kw-bio\">ALAT</span> &lt; 5N. Confirmation : <span class=\"kw-bio\">goutte épaisse</span> + <span class=\"kw-bio\">frottis mince</span>, <span class=\"kw-bio\">TDR</span>, <span class=\"kw-bio\">biologie moléculaire</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Urgence diagnostique ET thérapeutique</span> — 1ʳᵉ cause devant toute <span class=\"kw-clinique\">fièvre</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> suivant le retour</li><li>Recherche des <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> et traitement spécifique : <em>cf. item 170 (<span class=\"kw-clinique\">Paludisme</span>)</em></li></ul>"},{"id":"q-syndrome","kind":"decision","label":"Syndrome dominant après élimination du paludisme — Orientation selon les signes, la durée d’incubation et l’exposition","branches":[{"to":"q-fhv","label":"Fièvre + signes hémorragiques","color":"red"},{"to":"q-diarrhee","label":"Diarrhée fébrile / troubles digestifs","color":"amber"},{"to":"q-incub","label":"Autre orientation : incubation / exposition","color":"blue"}]},{"id":"q-fhv","kind":"decision","label":"Retour de zone à risque de fièvre hémorragique virale ?","branches":[{"to":"t-fhv","label":"OUI — suspicion de FHV","color":"red"},{"to":"t-hemorr","label":"NON — autres causes de fièvre hémorragique","color":"amber"}]},{"id":"t-fhv","kind":"terminal","label":"Fièvre hémorragique virale","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-etio\">Ebola</span>, <span class=\"kw-etio\">Marburg</span>, <span class=\"kw-etio\">Lassa</span> — <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-alerte\">syndrome hémorragique</span> au retour d’une zone à risque</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Isolement et signalement immédiats</span></li><li><span class=\"kw-ttt\">Précautions complémentaires</span> renforcées pour la protection du patient ET du personnel</li><li>Prise en charge guidée par le <span class=\"kw-def\">CNR des fièvres hémorragiques virales</span> et <span class=\"kw-def\">Santé publique France</span> — <span class=\"kw-clinique\">les</span> contacter <strong>avant tout prélèvement</strong></li></ul><h4>Pièges</h4><ul><li>Ebola, Marburg et Lassa ne sont <strong>pas</strong> des <span class=\"kw-etio\">arboviroses</span></li></ul>"},{"id":"t-hemorr","kind":"terminal","label":"Autres fièvres avec signes hémorragiques","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Paludisme</span> (à réitérer si forte présomption)</li><li><span class=\"kw-etio\">Hépatite</span> fulminante</li><li><span class=\"kw-etio\">Leptospirose</span> ictéro-<span class=\"kw-etio\">hémorragique</span></li><li><span class=\"kw-etio\">Dengue</span> et autres <span class=\"kw-etio\">arboviroses</span> hémorragiques (<span class=\"kw-etio\">fièvre jaune</span>)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> et <span class=\"kw-def\">surveillance</span> ; la <span class=\"kw-etio\">fièvre jaune</span> expose à une <span class=\"kw-alerte\">insuffisance hépatocellulaire et rénale</span> (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">20 %</span>)</li></ul>"},{"id":"q-diarrhee","kind":"decision","label":"Turista banale ou infection systémique ?","branches":[{"to":"t-turista","label":"Diarrhée aiguë banale","color":"green"},{"to":"t-typhoide","label":"Syndrome typhoïdique","color":"amber"}]},{"id":"t-turista","kind":"terminal","label":"Diarrhée du voyageur (turista)","color":"green","detail":"<h4>Clinique</h4><ul><li>Survient souvent la <span class=\"kw-chiffre\">1ʳᵉ semaine</span> du séjour ; guérison spontanée en <span class=\"kw-chiffre\">3-5 jours</span> ; germe principal <span class=\"kw-etio\">E. coli entérotoxinogène</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Réhydratation</span> dans tous <span class=\"kw-clinique\">les</span> cas (<span class=\"kw-ttt\">SRO</span> chez l’enfant)</li><li><span class=\"kw-ttt\">Racécadotril</span> si nécessaire</li><li><span class=\"kw-ttt\">Antibiothérapie</span> non recommandée en routine</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">Azithromycine</span> en 1ʳᵉ intention (ou <span class=\"kw-ttt\">ciprofloxacine</span>), <span class=\"kw-chiffre\">1 à 5 jours</span> — seulement si <span class=\"kw-clinique\">diarrhée</span> invasive ou cholériforme intense persistant <span class=\"kw-chiffre\">&gt; 48 h</span> sans recours possible aux soins locaux</li></ul>"},{"id":"t-typhoide","kind":"terminal","label":"Fièvre typhoïde","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Céphalées</span>, insomnie, <span class=\"kw-clinique\">pouls dissocié</span>, <span class=\"kw-clinique\">splénomégalie</span>, <span class=\"kw-clinique\">tuphos</span>, <span class=\"kw-clinique\">diarrhée « jus de melon »</span> ; transmission oro-fécale, réservoir strictement humain</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Leuco-neutropénie</span>, <span class=\"kw-bio\">CRP</span> élevée ; confirmation par <span class=\"kw-bio\">hémocultures</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">C3G parentérale</span> en probabiliste, puis adaptation à l’<span class=\"kw-bio\">antibiogramme</span> (<span class=\"kw-ttt\">fluoroquinolone</span>, <span class=\"kw-ttt\">C3G parentérale</span> ou <span class=\"kw-ttt\">azithromycine</span>)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Maladie à déclaration obligatoire</span> ; complications : <span class=\"kw-alerte\">hémorragies</span> et <span class=\"kw-alerte\">perforations digestives</span></li></ul>"},{"id":"q-incub","kind":"decision","label":"Durée d’incubation et exposition","branches":[{"to":"t-arbo","label":"Incubation brève / piqûre Aedes","color":"blue"},{"to":"t-schisto","label":"Baignade en eau douce + hyperéosinophilie","color":"blue"},{"to":"t-amoebose","label":"Hépatomégalie douloureuse / incubation longue","color":"blue"}]},{"id":"t-arbo","kind":"terminal","label":"Arbovirose (dengue ++)","color":"blue","detail":"<h4>Clinique</h4><ul><li>2ᵉ étiologie la plus fréquente après le <span class=\"kw-etio\">paludisme</span> ; <span class=\"kw-clinique\">myalgies</span>, <span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-clinique\">rash</span>, <span class=\"kw-clinique\">splénomégalie</span> ; contamination par l’<span class=\"kw-etio\">Aedes</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Leucopénie</span> ++, <span class=\"kw-bio\">thrombopénie</span> ++, <span class=\"kw-bio\">CRP</span> basse, <span class=\"kw-bio\">ALAT</span> &lt; 5N ; <span class=\"kw-bio\">PCR</span> durant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 premiers jours</span> de <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-bio\">sérologie</span> au-delà</li></ul><h4>Traitement</h4><ul><li>Uniquement <strong>symptomatique</strong> ; <span class=\"kw-alerte\">déclaration obligatoire</span> en métropole (<span class=\"kw-etio\">dengue</span>, <span class=\"kw-etio\">chikungunya</span>)</li></ul>"},{"id":"t-schisto","kind":"terminal","label":"Schistosomose (phase d’invasion)","color":"blue","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Prurit</span>, <span class=\"kw-clinique\">urticaire</span>, <span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-clinique\">hépatomégalie</span>, <span class=\"kw-clinique\">toux</span> ; contamination par <span class=\"kw-def\">contact</span> cutané avec une <span class=\"kw-etio\">eau douce</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hyperéosinophilie</span>, <span class=\"kw-bio\">CRP</span> élevée ; <span class=\"kw-bio\">sérologie</span> en phase d’invasion, recherche d’œufs (<span class=\"kw-clinique\">selles</span>, <span class=\"kw-clinique\">urines</span>) en phase d’état</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Praziquantel</span></li></ul>"},{"id":"t-amoebose","kind":"terminal","label":"Amoebose hépatique","color":"blue","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Hépatomégalie douloureuse</span> fébrile ; transmission oro-fécale</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hyperleucocytose à PNN</span>, <span class=\"kw-bio\">CRP</span> élevée ; <span class=\"kw-imagerie\">échographie</span> hépatique ± <span class=\"kw-imagerie\">TDM</span>, <span class=\"kw-bio\">sérologie</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Métronidazole</span> (nitro-imidazolé)</li></ul><h4>Pièges</h4><ul><li>L’amoebose <strong>intestinale aiguë</strong> ne donne <strong>pas</strong> de <span class=\"kw-clinique\">fièvre</span> — seule l’amoebose <strong>hépatique</strong> est fébrile</li></ul>"}]},"cards":[{"i":"18f5e9359f33","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quelles sont les caractéristiques du voyageur à considérer pour l'évaluation du risque sanitaire ?","a":"<div class=\"notion-course\"><ul><li>L'<strong>âge</strong>.</li><li>L'état de <strong>grossesse</strong>.</li><li>Les <strong>comorbidités</strong> existantes.</li><li>Le <strong>statut immunitaire et vaccinal</strong>.</li><li>Le <strong>budget</strong>, qui peut influencer l'accès aux vaccins et chimioprophylaxies non remboursés.</li></ul></div>"},{"i":"7df5276cd888","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quels sont les trois paramètres essentiels à analyser systématiquement pour évaluer le risque sanitaire individuel avant un voyage international ?","a":"<div class=\"notion-course\"><p>L'évaluation repose sur le croisement de trois paramètres : la <strong>destination</strong>, les <strong>modalités du voyage</strong> et les caractéristiques du <strong>voyageur</strong>.</p></div>"},{"i":"98645b1fba77","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quels facteurs liés à la destination doivent être pris en compte lors de l'évaluation du risque sanitaire pré-voyage ?","a":"<div class=\"notion-course\"><ul><li>La <strong>situation sanitaire et politique</strong> du pays.</li><li>La <strong>saison</strong> du voyage.</li><li>Les <strong>zones spécifiques visitées</strong> (rurales ou urbaines).</li></ul></div>"},{"i":"ab99a29ac68f","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quelles sont les principales sources numériques officielles d'information pour les recommandations aux voyageurs en France ?","a":"<div class=\"notion-course\"><p>Les recommandations sont émises par le <strong><span class=\"nc-yellow_bg\">Comité des maladies liées aux voyages et des maladies d'importation (CMVI) du HCSP</span></strong> et sont publiées dans le <strong><span class=\"nc-blue_bg\">Bulletin épidémiologique hebdomadaire</span> (BEH)</strong>. Elles sont actualisées en fonction de la situation internationale.</p></div>"},{"i":"ce5b23b0bd56","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quelles populations sont considérées spécifiquement à risque pour les voyages internationaux ?","a":"<div class=\"notion-course\"><ul><li>Les <strong>adultes jeunes</strong> effectuant des voyages non organisés de plusieurs semaines vers des destinations telles que l'Afrique subsaharienne ou l'Inde.</li><li>Les <strong>sujets émigrés</strong> retournant dans leur pays d'origine.</li><li>Les <strong>immunodéprimés</strong>.</li></ul></div>"},{"i":"e711d439361e","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quels éléments liés aux modalités du voyage sont importants pour l'évaluation du risque sanitaire individuel ?","a":"<div class=\"notion-course\"><ul><li>Le <strong>moyen de transport</strong>.</li><li>Les <strong>conditions de logement</strong>.</li><li>Les <strong>activités prévues</strong> (baignade, randonnée).</li><li>Le type de voyage (organisé ou aventureux).</li><li>La <strong>durée du séjour</strong>, car une exposition ponctuelle suffit pour le <span class=\"nc-pink nc-bold\">paludisme</span>, la <span class=\"nc-pink nc-bold\">fièvre jaune</span> et la <span class=\"nc-pink nc-bold\">dengue</span>.</li></ul></div>"},{"i":"89a5a7bdf4bc","n":175,"o":"175-14","u":"Étiologies","t":"Connaître les principales étiologies des diarrhées d’importation","q":"Quelles sont les causes médicamenteuses des diarrhées d'importation ?","a":"<div class=\"notion-course\"><p>Les causes médicamenteuses des diarrhées d'importation sont :</p><ul><li>Les <strong>AINS</strong> (anti-inflammatoires non stéroïdiens).</li><li>Certains <strong>antipaludiques</strong> comme l'<strong><span class=\"nc-pink_bg\">atovaquone-proguanil</span></strong> et la <strong>chloroquine-proguanil</strong>.</li></ul></div>"},{"i":"9ca1f702462b","n":175,"o":"175-14","u":"Étiologies","t":"Connaître les principales étiologies des diarrhées d’importation","q":"Quels pièges diagnostiques concernant le paludisme et l'amibiase faut-il connaître face à une diarrhée d'importation ?","a":"<div class=\"notion-course\"><p>Il faut connaître les pièges diagnostiques suivants :</p><ul><li>Le <strong><span class=\"nc-red nc-bold\">paludisme</span></strong> peut se présenter comme une <strong><span class=\"nc-red nc-bold\">diarrhée</span> non fébrile atypique</strong>.</li><li>L'<strong><span class=\"nc-green nc-bold\">amoebose intestinale aiguë</span></strong><span class=\"nc-green nc-bold\"> ne donne </span><strong><span class=\"nc-green nc-bold\">pas de fièvre</span></strong>, alors que l'<span class=\"nc-red nc-bold\">amoebose hépatique</span>, en revanche, peut s'accompagner de diarrhées fébriles.</li></ul></div>"},{"i":"bf548ed53aa0","n":175,"o":"175-14","u":"Étiologies","t":"Connaître les principales étiologies des diarrhées d’importation","q":"Quelles sont les principales étiologies des diarrhées d'importation non fébriles, souvent subaiguës ?","a":"<div class=\"notion-course\"><p>Les principales étiologies des diarrhées d'importation non fébriles, souvent subaiguës, incluent :</p><ul><li>Le <strong>paludisme</strong> (10 % de présentations atypiques).</li><li>Le <strong>choléra</strong>.</li><li>Les <strong><span class=\"nc-orange_bg\">helminthoses intestinales</span></strong> (orientées par l'hyperéosinophilie).</li><li>Les <strong>protozooses</strong> : <ul><li>La <strong><span class=\"nc-red nc-bold\">giardose</span></strong> (cause la plus fréquente de diarrhée prolongée non fébrile au retour des tropiques).</li><li>L'<strong><span class=\"nc-red nc-bold\">amoebose intestinale aiguë</span></strong>.</li><li>La <strong>cyclosporose</strong>.</li></ul></li></ul></div>"},{"i":"bfd10126c79c","n":175,"o":"175-14","u":"Étiologies","t":"Connaître les principales étiologies des diarrhées d’importation","q":"Quelles sont les principales étiologies des diarrhées d'importation fébriles ?","a":"<div class=\"notion-course\"><p>Les principales étiologies des diarrhées d'importation fébriles, souvent aiguës, incluent :</p><ul><li>La <strong>turista</strong>.</li><li>Le <strong><span class=\"nc-red_bg\">paludisme</span></strong> (à évoquer en premier, surtout chez l'enfant).</li><li>Les infections bactériennes avec syndrome dysentérique : <strong><span class=\"nc-purple_bg\">shigellose</span></strong>, <strong><span class=\"nc-purple_bg\">salmonelloses</span></strong>, <strong><span class=\"nc-purple_bg\">Campylobacter</span></strong> (nécessite une coproculture).</li><li>La <strong><span class=\"nc-green_bg\">primo-infection VIH</span></strong>.</li><li>Les <strong>hépatites A et E</strong>.</li><li>L'infection à <strong><span class=\"nc-purple_bg\">Clostridioides difficile</span></strong> en cas d'antibiothérapie récente.</li></ul></div>"},{"i":"21ead1429873","n":175,"o":"175-15","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","q":"Quelle est la prise en charge initiale d'une diarrhée du voyageur ?","a":"<div class=\"notion-course\"><ul><li>La <strong>réhydratation</strong> est essentielle dans tous les cas, avec des Sels de Réhydratation Orale (<span class=\"nc-green_bg\">SRO</span>) chez l'enfant.</li><li>Le <strong><span class=\"nc-pink_bg\">racécadotril</span></strong> (<span class=\"nc-pink_bg\">antidiarrhéique antisécrétoire</span>) peut être utilisé si nécessaire.</li><li>L'antibiothérapie n'est <strong>pas recommandée en routine</strong>.</li></ul></div>"},{"i":"78441fc63ab4","n":175,"o":"175-15","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","q":"Quelle est la démarche diagnostique devant une suspicion de protozoose (diarrhée prolongée) au retour d'un voyage ?","a":"<div class=\"notion-course\"><ul><li>Réaliser un <strong><span class=\"nc-blue\">examen parasitologique des selles</span></strong>.</li><li>Si celui-ci est difficile, un <strong>traitement d'épreuve par nitro-imidazolé (<span class=\"nc-pink\">métronidazole</span>)</strong> peut être envisagé.</li><li>En cas d'échec de ce traitement, une <strong><span class=\"nc-blue\">coloscopie</span></strong> peut parfois être nécessaire.</li></ul></div>"},{"i":"8218f240cfc4","n":175,"o":"175-15","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","q":"Dans quels cas une antibiothérapie est-elle indiquée pour la diarrhée du voyageur et quel est le traitement de première intention ?","a":"<div class=\"notion-course\"><p>Une antibiothérapie est indiquée uniquement en cas de <strong><span class=\"nc-red_bg\">diarrhée invasive</span></strong>, ou de <strong>diarrhée cholériforme intense persistant plus de 48 heures</strong> sans accès aux soins locaux. Le traitement de première intention est l'<strong><span class=\"nc-pink_bg\">azithromycine</span></strong> (ou la ciprofloxacine) pendant <span class=\"nc-pink nc-bold\">1 à 5 jours</span>.</p></div>"},{"i":"d281d0bd46b2","n":175,"o":"175-15","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","q":"Quels sont les agents infectieux majoritaires responsables de la diarrhée du voyageur ?","a":"<div class=\"notion-course\"><ul><li>Les <strong>bactéries</strong> (environ 50%), principalement E. coli entérotoxinogène (ETEC).</li><li>Les <strong>virus</strong> (5-25%), notamment les <span class=\"nc-purple_bg\">norovirus</span>.</li><li>Les <strong>parasites</strong> (moins de 10%), principalement les protozoaires et les <span class=\"nc-purple_bg\">amibes</span>.</li></ul></div>"},{"i":"f12832817d4f","n":175,"o":"175-15","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","q":"Quelle est l'étiologie bactérienne la plus fréquente de la diarrhée du voyageur ?","a":"<div class=\"notion-course\"><p>La bactérie la plus fréquemment impliquée dans la diarrhée du voyageur est <strong>E. coli entérotoxinogène (ETEC)</strong>.</p></div>"},{"i":"07a15c2cb942","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Quels sont les éléments essentiels à inclure dans la trousse de médicaments du voyageur en pays tropical ?","a":"<div class=\"notion-course\"><ul><li>Un <strong>antalgique/antipyrétique</strong> (paracétamol).</li><li>Un <strong>antidiarrhéique</strong> (<span class=\"nc-pink_bg\">racécadotril</span>).</li><li>Un <strong>antiémétique</strong>.</li><li>Un <strong>antibiotique</strong> (si absence de soins locaux).</li><li>Un <strong>anti-H1</strong> de dernière génération.</li><li>Un <strong>antipaludique préventif</strong> si nécessaire.</li></ul></div>"},{"i":"4e9667caa565","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Comment la gestion des maladies chroniques doit-elle être abordée avant un voyage dans un pays tropical ?","a":"<div class=\"notion-course\"><p>Avant un voyage, il est primordial de procéder à une <strong>évaluation médicale</strong> complète de la maladie chronique. Il faut emporter tous les <strong>documents médicaux</strong> pertinents, idéalement traduits en anglais. Dans certains cas, le voyage peut être <strong>contre-indiqué</strong> en fonction de la pathologie chronique.</p></div>"},{"i":"51441922c887","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Quelles sont les mesures de prévention solaire et de baignade recommandées lors d'un voyage en pays tropical ?","a":"<div class=\"notion-course\"><ul><li><strong>Pas d'exposition solaire avant 1 an</strong> chez l'enfant.</li><li>Utilisation d'une <strong>crème solaire FPS ≥ 30</strong>, réappliquée toutes les <strong>2 heures</strong>.</li><li>Port de <strong>lunettes de soleil enveloppantes</strong> à verres filtrants CE 3 ou 4.</li><li><strong>Éviter la baignade en eau douce stagnante</strong> pour prévenir la schistosomose et la <span class=\"nc-orange_bg nc-bold\">leptospirose</span>.</li><li><strong><span class=\"nc-green_bg\">Ne pas marcher pieds nus</span></strong><span class=\"nc-green_bg\"> en extérieur</span> pour éviter l'anguillulose et l'ankylostomose.</li></ul></div>"},{"i":"6e096447db3f","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Quelles sont les molécules de chimioprophylaxie antipaludique recommandées pour l'Afrique subsaharienne et leurs spécificités ?","a":"<div class=\"notion-course\"><ul><li><strong><span class=\"nc-pink_bg\">Atovaquone-proguanil</span></strong> : prise quotidienne <strong>pendant le séjour</strong> et <strong><span class=\"nc-green_bg\">1 semaine</span> après le retour</strong> (<span class=\"nc-green nc-bold\">agit sur les formes hépatiques</span>). Utilisable dès <strong>≥ 11 kg</strong>.</li><li><strong><span class=\"nc-pink_bg\">Méfloquine</span></strong> : début <strong><span class=\"nc-red_bg\">10 jours avant</span></strong><span class=\"nc-red_bg\"> le départ</span>, prise <strong>hebdomadaire</strong>, poursuivie <strong><span class=\"nc-orange_bg\">3 semaines</span> après le retour</strong> (nécessite un test de tolérance). Utilisable dès <strong>≥ 15 kg</strong>. Contre-indications : antécédents de <span class=\"nc-red nc-bold\">dépression</span> ou de convulsions, prise de <span class=\"nc-orange_bg\">valproate de sodium</span>.</li><li><strong>Doxycycline</strong> : prise quotidienne <strong>pendant le séjour</strong> et <strong><span class=\"nc-red_bg\">4 semaines</span> après le retour</strong>. Utilisable dès <strong>≥ 8 ans</strong>.</li></ul></div>"},{"i":"867dcfa670f5","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Quels sont les principaux vecteurs et les maladies associées à la piqûre d'arthropodes dans les régions tropicales ?","a":"<div class=\"notion-course\"><ul><li>L'<strong>Anophèle</strong> (pique la <span class=\"nc-brown_bg nc-bold\">nuit</span>) transmet le <strong><span class=\"nc-pink nc-bold\">paludisme</span></strong>.</li><li>Culex : notamment West Nile et <span class=\"nc-brown_bg\">encéphalite japonaise</span>. Les tiques transmettent notamment borréliose de Lyme, certaines <span class=\"nc-orange_bg\">rickettsioses</span> et <span class=\"nc-brown_bg\">encéphalite à tiques</span>.</li><li>L'<strong>Aedes</strong> (pique le <span class=\"nc-brown_bg nc-bold\">jour</span>) transmet la <strong><span class=\"nc-pink nc-bold\">dengue</span></strong>, le <strong>Zika</strong>, le <strong>chikungunya</strong> et la <strong><span class=\"nc-pink nc-bold\">fièvre jaune</span></strong>.</li></ul></div>"},{"i":"f02d15ca6f72","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Quelles sont les mesures d'hygiène alimentaire essentielles pour prévenir les maladies à transmission oro-fécale en voyage tropical ?","a":"<div class=\"notion-course\"><ul><li><strong>Lavage des mains</strong> fréquent (eau et savon ou SHA).</li><li>Consommation d'<strong>eau en bouteille encapsulée</strong>, ou rendue potable (filtration, ébullition, désinfectant).</li><li>Consommation de lait <strong>pasteurisé ou bouilli</strong> et de viandes/poissons <strong>bien cuits et consommés chauds</strong>.</li><li><strong>Peler les fruits</strong> soi-même.</li><li><strong>Éviter les crudités</strong>, les fruits de mer crus, les buffets froids, les glaçons et les glaces.</li><li>Se méfier de la <strong><span class=\"nc-red nc-bold\">ciguatera</span></strong> (gros poissons de mer).</li></ul></div>"},{"i":"0aa43ff53aaa","n":175,"o":"175-3","u":"Prise en charge","t":"Identifier les personnes avec une fragilité particulière","q":"Quels sont les enjeux spécifiques pour le jeune enfant et le nourrisson lors d'un voyage en pays tropical ?","a":"<div class=\"notion-course\"><ul><li>Risque de déshydratation et d’infections, prévention des piqûres, soleil et accidents ; vérifier âge minimal des vaccins et médicaments. Répulsif choisi selon AMM/RCP et recommandations, sans généralisation par molécule ou concentration ; privilégier aussi vêtements et moustiquaire.</li></ul></div>"},{"i":"4afec477f036","n":175,"o":"175-3","u":"Prise en charge","t":"Identifier les personnes avec une fragilité particulière","q":"Quelles précautions spécifiques doivent être prises lors d'un voyage en pays tropical pour une femme enceinte ?","a":"<div class=\"notion-course\"><p>Pour une femme enceinte, le <strong>vaccin anti-amarile est déconseillé</strong>. Le <strong><span class=\"nc-red nc-bold\">paludisme</span></strong> est volontiers plus grave et certains <strong>antipaludiques et répulsifs</strong> peuvent être limités ou contre-indiqués. Une évaluation renforcée est donc essentielle.</p></div>"},{"i":"a965370c45fa","n":175,"o":"175-3","u":"Prise en charge","t":"Identifier les personnes avec une fragilité particulière","q":"Quels sont les profils de voyageurs considérés comme fragiles nécessitant une évaluation pré-voyage renforcée ?","a":"<div class=\"notion-course\"><ul><li>Immunodépression, grossesse, très jeune âge, âge avancé ou maladie chronique justifient une préparation adaptée. Les voyageurs rendant visite à leurs proches peuvent aussi avoir des expositions importantes et une prévention insuffisante, sans être tous médicalement fragiles.</li></ul></div>"},{"i":"ca65826b306a","n":175,"o":"175-3","u":"Prise en charge","t":"Identifier les personnes avec une fragilité particulière","q":"Quelles sont les spécificités et les précautions à prendre concernant la vaccination chez le voyageur immunodéprimé ?","a":"<div class=\"notion-course\"><ul><li>Vérifier type et degré d’immunodépression : les vaccins vivants sont habituellement contre-indiqués dans les immunodépressions significatives ; les vaccins inactivés peuvent être moins immunogènes.</li><li>Chez certaines personnes vivant avec le VIH et avec immunité préservée, une vaccination amarile peut être possible après évaluation spécialisée du risque, des CD4 et du contexte. Ne pas appliquer un seuil unique à tous les âges et situations.</li></ul></div>"},{"i":"e5a0c58b5b05","n":175,"o":"175-3","u":"Prise en charge","t":"Identifier les personnes avec une fragilité particulière","q":"Pourquoi les sujets émigrés retournant dans leur pays d'origine représentent-ils un profil de risque particulier lors d'un voyage en pays tropical ?","a":"<div class=\"notion-course\"><p>Les sujets émigrés retournant au pays d'origine présentent un risque particulier en raison de leur <strong>moindre recours à la prévention</strong>, d'une <strong>perte d'immunité</strong> au fil du temps, et de séjours souvent <strong>longs</strong> dans des <strong>zones rurales</strong> à plus haut risque d'exposition.</p></div>"},{"i":"5d17aa833009","n":175,"o":"175-5","u":"Prise en charge","t":"Connaître les vaccinations spécifiques du voyageur","q":"Quelles sont les caractéristiques du vaccin contre la fièvre jaune (anti-amarile), y compris ses contre-indications et son statut obligatoire ?","a":"<div class=\"notion-course\"><p>Le vaccin contre la <span class=\"nc-pink nc-bold\">fièvre jaune</span> est un <span class=\"nc-red_bg\">vaccin </span><strong><span class=\"nc-red_bg\">vivant atténué</span></strong>. Ses caractéristiques sont :</p><ul><li><strong>Contre-indications</strong> : Déconseillé pendant la <strong><span class=\"nc-red nc-bold\">grossesse</span></strong> et chez l'<strong><span class=\"nc-red nc-bold\">immunodéprimé</span></strong> (possible dans le VIH si <strong>CD4 &gt; 200/mm³</strong> et <strong>&gt; 15 % de lymphocytes</strong>).</li><li><strong>Obligatoire ou recommandé</strong> pour l'<strong><span class=\"nc-green_bg\">Afrique intertropicale</span></strong> et la <strong><span class=\"nc-green_bg\">région amazonienne</span></strong>, absent en Asie et en <span class=\"nc-green_bg\">Océanie</span>.</li><li>Authentifié par un <span class=\"nc-yellow_bg\">médecin d'un </span><strong><span class=\"nc-yellow_bg\">Centre agréé de Vaccinations Internationales</span></strong> sur le carnet international.</li><li>Efficace <strong>10 jours après l'injection</strong> et pour <strong><span class=\"nc-red nc-bold\">toute la vie</span></strong> (sauf injection avant 2 ans ou pendant la <span class=\"nc-red nc-bold\">grossesse</span> où un rappel pourrait être envisagé).</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-pink nc-bold\">Fièvre jaune</span> : certificat international généralement valable à vie ; les indications médicales éventuelles de rappel sont distinctes des règles du certificat. Vaccins du voyage selon exposition et calendrier 2026, y compris ROR anticipé dans certaines situations ; une dose avant douze mois ne remplace pas les deux doses ultérieures. Vérifier l’âge autorisé de chaque spécialité.</li></ul></div></div>"},{"i":"9e9bad7661d4","n":175,"o":"175-5","u":"Prise en charge","t":"Connaître les vaccinations spécifiques du voyageur","q":"Quels sont les vaccins recommandés pour le voyageur selon les indications géographiques ou les conditions de séjour ?","a":"<div class=\"notion-course\"><p>Les vaccins <span class=\"nc-blue nc-bold\">recommandés</span> et leurs indications sont :</p><ul><li><strong>Hépatite B</strong> : Séjour fréquent ou prolongé en zone d'endémie.</li><li><strong>Hépatite A</strong> (dès <strong>1 an</strong>) : Séjour en pays à hygiène précaire.</li><li><strong>Typhoïde</strong> (dès <strong>2 ans</strong>, rappel tous les <strong><span class=\"nc-pink nc-bold\">3 ans</span></strong>) : Séjours prolongés en pays à bas niveau d'hygiène (<span class=\"nc-green_bg\">sous-continent indien</span> ++).</li><li><strong>Rage</strong> (<span class=\"nc-pink nc-bold\">dès l'âge de la marche</span>) : <span class=\"nc-yellow_bg\">Séjour prolongé, aventureux</span> ou isolé en zone à risque (Asie, Afrique, <span class=\"nc-red_bg\">Amérique du Sud</span>).</li><li><strong>Méningocoque ACYW conjugué</strong> (dès <strong>1 an</strong> pour l'enfant voyageur) : <span class=\"nc-red nc-bold\">Ceinture de la méningite en Afrique</span> en saison sèche (<strong><span class=\"nc-red nc-bold\">novembre-juin</span></strong>) et contact étroit et prolongé avec la population.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-pink nc-bold\">Fièvre jaune</span> : certificat international généralement valable à vie ; les indications médicales éventuelles de rappel sont distinctes des règles du certificat. Vaccins du voyage selon exposition et calendrier 2026, y compris ROR anticipé dans certaines situations ; une dose avant douze mois ne remplace pas les deux doses ultérieures. Vérifier l’âge autorisé de chaque spécialité.</li></ul></div></div>"},{"i":"e16a240cf3d6","n":175,"o":"175-5","u":"Prise en charge","t":"Connaître les vaccinations spécifiques du voyageur","q":"Quels sont les vaccins de routine à considérer chez l'enfant non vacciné avant un séjour prolongé en pays de forte endémie ?","a":"<div class=\"notion-course\"><p>Pour un enfant non vacciné, en cas de séjour prolongé (<strong>&gt; 1 mois</strong>) en pays de forte endémie, il convient de considérer :</p><ul><li>Le <strong>BCG</strong>.</li><li>Le vaccin <strong>anti-rougeoleux</strong> (dès <strong>6 mois</strong>, vaccin monovalent).</li><li>Le <span class=\"nc-yellow_bg\">vaccin contre l'</span><strong><span class=\"nc-yellow_bg\">hépatite B</span></strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-pink nc-bold\">Fièvre jaune</span> : certificat international généralement valable à vie ; les indications médicales éventuelles de rappel sont distinctes des règles du certificat. Vaccins du voyage selon exposition et calendrier 2026, y compris ROR anticipé dans certaines situations ; une dose avant douze mois ne remplace pas les deux doses ultérieures. Vérifier l’âge autorisé de chaque spécialité.</li></ul></div></div>"},{"i":"e62b588fd499","n":175,"o":"175-5","u":"Prise en charge","t":"Connaître les vaccinations spécifiques du voyageur","q":"À partir de quel âge les enfants peuvent-ils recevoir les vaccins contre la Fièvre jaune, l'Hépatite A, la Typhoïde et la Rage, et quelles sont les régions concernées pour chacun ?","a":"<div class=\"notion-course\"><p>Les âges minimaux et les régions concernées pour les vaccins spécifiques aux enfants voyageurs sont :</p><ul><li><strong><span class=\"nc-pink nc-bold\">Fièvre jaune</span></strong> : <strong>9 mois</strong> (<strong>6 mois si épidémie</strong>) pour les régions intertropicales d'Afrique et d'<span class=\"nc-red_bg\">Amérique du Sud</span>.</li><li><strong>Hépatite A</strong> : <strong>1 an</strong> pour toutes destinations tropicales ou peu hygiéniques.</li><li><strong>Typhoïde</strong> : <strong>2 ans</strong> pour le <span class=\"nc-green_bg\">sous-continent indien</span>, l'<span class=\"nc-green_bg\">Asie du Sud-Est</span>, l'Afrique.</li><li><strong>Rage</strong> : <span class=\"nc-pink nc-bold\">Dès l'</span><strong><span class=\"nc-pink nc-bold\">âge de la marche</span></strong> pour l'Asie, l'<span class=\"nc-red_bg\">Amérique du Sud</span>, l'Afrique en cas de séjour isolé ou prolongé.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-pink nc-bold\">Fièvre jaune</span> : certificat international généralement valable à vie ; les indications médicales éventuelles de rappel sont distinctes des règles du certificat. Vaccins du voyage selon exposition et calendrier 2026, y compris ROR anticipé dans certaines situations ; une dose avant douze mois ne remplace pas les deux doses ultérieures. Vérifier l’âge autorisé de chaque spécialité.</li></ul></div></div>"},{"i":"f1c340cefe6d","n":175,"o":"175-5","u":"Prise en charge","t":"Connaître les vaccinations spécifiques du voyageur","q":"Quelles sont les trois catégories de vaccinations à considérer pour le voyageur, selon les recommandations médicales ?","a":"<div class=\"notion-course\"><p>La vaccination du voyageur s'organise en trois catégories :</p><ul><li>Mise à jour des <strong>vaccins de routine</strong>.</li><li>Vaccins <strong><span class=\"nc-red nc-bold\">obligatoires</span></strong>.</li><li>Vaccins <strong><span class=\"nc-blue nc-bold\">recommandés</span></strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-pink nc-bold\">Fièvre jaune</span> : certificat international généralement valable à vie ; les indications médicales éventuelles de rappel sont distinctes des règles du certificat. Vaccins du voyage selon exposition et calendrier 2026, y compris ROR anticipé dans certaines situations ; une dose avant douze mois ne remplace pas les deux doses ultérieures. Vérifier l’âge autorisé de chaque spécialité.</li></ul></div></div>"},{"i":"1e511d4a0f58","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quels sont les éléments clinico-biologiques évocateurs d'une arbovirose (notamment la dengue) au retour d'une zone tropicale ?","a":"<div class=\"notion-course\"><p>Les éléments évocateurs d'une arbovirose sont :</p><ul><li>Des <strong><span class=\"nc-blue_bg\">myalgies</span></strong>, <strong><span class=\"nc-blue_bg\">arthralgies</span></strong></li><li>Un <strong>rash</strong>, une <span class=\"nc-green nc-bold\">splénomégalie</span></li><li>Une <strong><span class=\"nc-orange_bg\">leucopénie</span></strong> ++ et une <strong><span class=\"nc-orange_bg\">thrombopénie</span></strong> ++</li><li>Une CRP basse</li><li>Des ALAT &lt; 5N</li></ul></div>"},{"i":"41c752df0e29","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quels sont les signes clinico-biologiques en faveur d'une hépatite virale d'importation (type A) au retour d'une zone tropicale ?","a":"<div class=\"notion-course\"><p>Une hépatite virale se manifeste par :</p><ul><li>Des <strong><span class=\"nc-blue_bg\">troubles digestifs</span></strong>, un <strong><span class=\"nc-red nc-bold\">ictère</span></strong></li><li>Une <span class=\"nc-purple nc-bold\">hépatomégalie</span>, un <span class=\"nc-orange nc-bold\">urticaire</span></li><li>Une leucopénie, une CRP basse</li><li>Des <strong>ALAT &gt; 10N</strong></li></ul></div>"},{"i":"809fd1fe46b8","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quelles sont les manifestations cliniques et biologiques d'une schistosomose en phase d'invasion après une exposition en zone tropicale ?","a":"<div class=\"notion-course\"><p>En phase d'invasion, la schistosomose peut présenter :</p><ul><li>Un <strong>prurit</strong>, un <span class=\"nc-orange nc-bold\">urticaire</span>, des arthralgies</li><li>Une <span class=\"nc-purple nc-bold\">hépatomégalie</span>, une toux</li><li>Une <strong>hyperéosinophilie</strong></li><li>Une CRP élevée</li></ul></div>"},{"i":"955deb05d1ee","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quels sont les signes cliniques et biologiques évocateurs d'une fièvre typhoïde après un voyage en région tropicale ?","a":"<div class=\"notion-course\"><p>La fièvre typhoïde se caractérise par :</p><ul><li>Des <strong>céphalées</strong> ++, une insomnie</li><li>Un <strong>pouls dissocié</strong> (<span class=\"nc-yellow_bg\">fièvre</span> haute et bradycardie relative)</li><li>Une splénomégalie</li><li>Une leucopénie, une CRP élevée</li><li>Des ALAT &lt; 5N</li></ul></div>"},{"i":"c18ca875fc35","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Comment s'oriente le diagnostic d'une rickettsiose ou d'une amœbose hépatique devant une fièvre au retour des tropiques ?","a":"<div class=\"notion-course\"><ul><li>Pour une <strong>rickettsiose</strong> : il faut rechercher une <strong><span class=\"nc-yellow_bg\">escarre d'inoculation</span></strong>, une <span class=\"nc-blue_bg\">éruption</span>, des <span class=\"nc-orange_bg\">adénopathies</span>, des <span class=\"nc-blue_bg\">céphalées</span>, associés à une <span class=\"nc-orange_bg\">leucopénie</span>, une <span class=\"nc-orange_bg\">thrombopénie</span> et une CRP élevée.</li><li>Pour une <strong>amœbose hépatique</strong> : elle se manifeste par une <strong><span class=\"nc-purple nc-bold\">hépatomégalie</span> douloureuse</strong> avec une hyperleucocytose à PNN et une CRP élevée.</li></ul></div>"},{"i":"dbab71ac66e0","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quelle est la première étiologie à évoquer devant toute fièvre survenant dans les 3 mois suivant un retour de zone d'endémie tropicale ?","a":"<div class=\"notion-course\"><p>La première étiologie à évoquer est le <strong><span class=\"nc-red_bg\">paludisme à </span><em><span class=\"nc-red_bg\">P. falciparum</span></em></strong>.</p></div>"},{"i":"f313147f9f30","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quels sont les principaux tableaux clinico-biologiques suggestifs d'un paludisme au retour d'une zone tropicale ?","a":"<div class=\"notion-course\"><p>Devant un paludisme, l'orientation clinico-biologique comprend :</p><ul><li>Des <strong><span class=\"nc-blue_bg\">troubles digestifs</span> et neurologiques</strong></li><li>Une <strong><span class=\"nc-green nc-bold\">splénomégalie</span></strong><span class=\"nc-green nc-bold\">,</span> une <span class=\"nc-purple nc-bold\">hépatomégalie</span></li><li>Une <strong>thrombopénie</strong> ++</li><li>Une anémie, une leucopénie</li><li>Une CRP élevée</li><li>Des ALAT &lt; 5N</li></ul></div>"},{"i":"05562f702729","n":175,"o":"175-9","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","q":"En cas de fièvre au retour des tropiques, quelles autres causes, infectieuses ou non infectieuses, doit-on également élargir le diagnostic ?","a":"<div class=\"notion-course\"><p>Il est important de penser aux causes <strong>non infectieuses</strong> comme la <strong>MTEV (Maladie Thromboembolique Veineuse)</strong>, une <strong>néoplasie</strong> ou une <strong>maladie inflammatoire</strong>. Il faut également considérer les causes <strong>infectieuses cosmopolites</strong> telles qu'une <strong>PNA (Pyélonéphrite Aiguë)</strong>, la <strong>grippe</strong> ou une <strong>pneumopathie</strong>.</p></div>"},{"i":"41e6cfcd02c4","n":175,"o":"175-9","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","q":"Quels sont les éléments clés à rechercher lors de l'interrogatoire d'un patient présentant de la fièvre au retour d'un voyage en zone tropicale ?","a":"<div class=\"notion-course\"><ul><li><strong>Destination précise</strong> et <strong>dates du séjour</strong>.</li><li>Durée d'incubation.</li><li>Prise ou non d'une <strong>chimioprophylaxie antipaludique</strong>.</li><li>Statut vaccinal.</li><li><strong>Activités à risque</strong> (baignade, contact animal, rapports sexuels non protégés).</li></ul></div>"},{"i":"7d6c79454104","n":175,"o":"175-9","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","q":"Quelle est l'attitude initiale systématique devant toute fièvre au retour d'un voyage en zone tropicale ?","a":"<div class=\"notion-course\"><p>Devant toute fièvre au retour d'un voyage en zone tropicale, l'urgence est d'éliminer un <strong><span class=\"nc-orange nc-bold\">paludisme</span></strong>. Toute fièvre au retour des tropiques est un <span class=\"nc-orange nc-bold\">paludisme</span> jusqu'à preuve du contraire.</p></div>"},{"i":"e84ef2fead9e","n":175,"o":"175-9","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","q":"Quels examens complémentaires sont prioritaires pour éliminer un paludisme à P. falciparum devant une fièvre au retour des tropiques ?","a":"<div class=\"notion-course\"><p>Il est impératif de réaliser sans délai un <strong>frottis-goutte épaisse</strong> et un <strong>TDR (Test de Diagnostic Rapide)</strong>. C'est une urgence diagnostique et thérapeutique. Le frottis-goutte épaisse prime sur tout autre examen dans ce contexte.</p></div>"},{"i":"fae225805915","n":175,"o":"175-9","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","q":"Quel bilan biologique complémentaire doit être réalisé en cas de fièvre au retour des tropiques, en l'absence d'orientation diagnostique évidente après le bilan initial ?","a":"<div class=\"notion-course\"><ul><li><strong>NFS</strong> (Numération Formule Sanguine).</li><li><strong>CRP</strong> (Protéine C Réactive).</li><li><strong>Transaminases</strong>.</li><li><strong>Hémocultures</strong>.</li><li><strong>Sérologies</strong> orientées par la clinique.</li></ul></div>"},{"i":"67fa14aeb26e","n":175,"o":"175-4","u":"Epidémiologie","t":"Connaître les principales infections acquises au cours d’un voyage en zone tropicale","q":"Quels sont les points essentiels concernant les principales infections acquises au cours d’un voyage en zone tropicale ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-pink_bg\">Atovaquone–proguanil</span> : début la veille de l’entrée en zone exposée, prise quotidienne et poursuite sept jours après la sortie. Dose selon poids ; l’usage entre 5 et moins de 11 kg est hors AMM et relève d’une prescription adaptée.</li><li>Doxycycline : début la veille, prise quotidienne et poursuite 28 jours après la sortie ; précautions œsophagiennes et photosensibilisation. Pour cette prophylaxie prolongée : contre-indication avant huit ans, pendant les deuxième et troisième trimestres et l’allaitement ; premier trimestre déconseillé.</li><li><span class=\"nc-pink_bg\">Méfloquine</span> : désormais en dernière intention, après évaluation des contre-indications et risques neuropsychiatriques. Début au moins dix jours avant le départ, prise hebdomadaire, poursuite trois semaines après la sortie selon HCSP 2026.</li><li>Pas de prescription uniforme : interactions, poids, grossesse, fonction rénale, tolérance et adhésion guident le choix. Un traitement de réserve est une stratégie exceptionnelle et ne remplace ni la prophylaxie indiquée ni l’accès aux soins.</li></ul></div>"},{"i":"af1993c0f03f","n":175,"o":"175-6","u":"Diagnostic positif","t":"Connaître les indications d’une sérologie hépatite A chez un patient à risque d’exposition antérieure","q":"Quels sont les points essentiels concernant les indications d’une sérologie hépatite A chez un patient à risque d’exposition antérieure ?","a":"<div class=\"notion-course\"><p>Le <span>VHA</span> est une <span>maladie immunisante</span> : un sujet ayant déjà contracté l'<span>hépatite</span> A est protégé à vie. La <span>sérologie VHA</span> permet d'identifier <span>les</span> patients <strong>déjà immunisés</strong>, à qui une <span>vaccination</span> serait inutile.</p>\n      <p>Indications d'une <span>sérologie VHA</span> <strong>avant de décider de vacciner</strong> (recherche d'une <span>immunité ancienne</span>, chez un patient à risque d'exposition antérieure) :</p>\n      <ul>\n        <li>Personnes <strong>nées en France avant 1945</strong> (<span>&gt; 75 ans</span>)</li>\n        <li>Personnes ayant <strong>vécu dans un pays d'endémie</strong></li>\n        <li>Personnes signalant un <strong>antécédent d'<span>ictère</span></strong></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales</em></p></div>"},{"i":"e6c44b43ce94","n":175,"o":"175-7","u":"Prise en charge","t":"Connaître les conseils de prévention vis-à-vis des parasitoses à transmission éco-orale ou transcutanée","q":"Quels sont les points essentiels concernant les conseils de prévention vis-à-vis des parasitoses à transmission éco-orale ou transcutanée ?","a":"<div class=\"notion-course\"><p><span>Les</span> parasitoses du voyageur se préviennent selon leur <strong>voie de transmission</strong> — deux mécanismes distincts.</p>\n      <div class=\"callout callout-info\"><strong>Transmission éco-orale</strong> (mains, eau, aliments souillés). Concerne <span>les</span> <span><span class=\"nc-red nc-bold\">parasitoses intestinales</span></span> (<span>protozooses</span>, helminthoses). Prévention : lavage des mains, eau encapsulée ou traitée, éviter les crudités et aliments souillés, peler les fruits.</div>\n      <div class=\"callout callout-info\"><strong>Transmission transcutanée</strong> (pénétration active de la larve à travers la peau). Prévention :\n        <ul>\n          <li>Pas de baignade en eau douce → <span><span class=\"nc-orange_bg nc-bold\">schistosomoses</span></span></li>\n          <li><span class=\"nc-green_bg\">Ne pas marcher pieds nus en extérieur</span> → <span>anguillulose (<span class=\"nc-orange_bg nc-bold\">strongyloïdose)</span></span>, <span><span class=\"nc-orange_bg nc-bold\">ankylostomose</span></span><span class=\"nc-orange_bg nc-bold\"> (</span><span><span class=\"nc-orange_bg nc-bold\">larva migrans cutanée</span></span><span class=\"nc-orange_bg nc-bold\">)</span></li>\n          <li><span class=\"nc-green_bg\">Ne pas s'allonger directement sur le</span> <span class=\"nc-green_bg nc-bold\">sable</span> contaminé <span class=\"nc-green_bg\">de certaines plages</span> → <span>ankylostomose</span></li>\n          <li>Repasser au fer chaud le linge séché au soleil → <span>myiase</span></li>\n        </ul>\n      </div></div>"},{"i":"2159dd858137","n":175,"o":"175-10","u":"Étiologies","t":"Connaître les signes d’orientation étiologiques en fonction des durées d’incubation","q":"Quels sont les points essentiels concernant les signes d’orientation étiologiques en fonction des durées d’incubation ?","a":"<div class=\"notion-course\"><p>La <strong>durée d'incubation</strong> (intervalle entre l'exposition et l'apparition de la <span>fièvre</span>) restreint fortement le champ étiologique.</p>\n      <table>\n        <thead><tr><th>Incubation</th><th>Étiologies à évoquer</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>&lt;<span> 7 jours</span></strong></td>\n            <td><strong><span class=\"nc-orange_bg\">Diarrhées infectieuses</span> :</strong> <span class=\"nc-purple_bg\">shigellose</span> ; choléra ; <span class=\"nc-purple_bg\">salmonelloses</span> non typhiques<br><strong>Arboviroses :</strong> dengue ; zika ; chikungunya</td>\n          </tr>\n          <tr>\n            <td><strong><span>7-14 jours</span></strong></td>\n            <td><span><span class=\"nc-red_bg\">Paludisme à </span><em><span class=\"nc-red_bg\">P. falciparum</span></em></span> ; <span><span class=\"nc-red_bg\">typhoïde</span></span> ; spirochétoses (<span class=\"nc-purple_bg\">leptospirose</span>, <span class=\"nc-purple_bg\">borrélioses</span>) ; <span class=\"nc-purple_bg\">rickettsioses</span></td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span> 2 semaines</span></strong></td>\n            <td><span><span class=\"nc-red_bg\">Paludisme</span></span><span class=\"nc-red_bg\"> à </span><em><span><span class=\"nc-red_bg\">P. falciparum</span></span></em> (jusqu'à<span> <span class=\"nc-pink nc-bold\">2 mois</span></span>) ; <span class=\"nc-red_bg\">typhoïde</span> (jusqu'à<span> <span class=\"nc-pink nc-bold\">3 semaines</span></span>) ; hépatites A, B et E ; <span><span class=\"nc-green_bg\">primo-infection VIH</span></span> (<span>2-8 semaines</span>) ; <span class=\"nc-orange_bg\">schistosomose en phase d'invasion</span> (<span>2-6 semaines</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Mois à années</strong></td>\n            <td><span class=\"nc-purple_bg\">Trypanosomoses</span> ; <span class=\"nc-purple_bg\">leishmaniose viscérale</span> ; <span><span class=\"nc-orange nc-bold\">paludisme</span></span> à <em>P. non falciparum</em> ; <span><span class=\"nc-red nc-bold\">amoebose hépatique</span></span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> L'<span class=\"nc-green nc-bold\">amoebose intestinale aiguë ne donne </span><strong><span class=\"nc-green nc-bold\">pas</span></strong><span class=\"nc-green nc-bold\"> de </span><span><span class=\"nc-green nc-bold\">fièvre</span></span> — seule l'<span class=\"nc-red nc-bold\">amoebose </span><strong><span class=\"nc-red nc-bold\">hépatique</span></strong> est fébrile.</div></div>"},{"i":"3380a42bacc2","n":175,"o":"175-11","u":"Diagnostic positif","t":"Connaître les modalités d’analyse de la courbe thermique en cas de fièvre au retour du voyage","q":"Quels sont les points essentiels concernant les modalités d’analyse de la courbe thermique en cas de fièvre au retour du voyage ?","a":"<div class=\"notion-course\"><p>L'<strong>allure de la courbe thermique</strong> et <span>les</span> signes cliniques associés affinent l'orientation étiologique.</p>\n      <table>\n        <thead><tr><th>Profil thermique</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Fièvre</span> récurrente</strong> (accès fébriles répétés)</td><td><span><span class=\"nc-orange_bg\">Paludisme</span></span> ; <span><span class=\"nc-purple_bg\">borréliose</span></span></td></tr>\n          <tr><td><strong><span><span class=\"nc-blue_bg\">Fièvre</span></span> <span class=\"nc-yellow_bg nc-bold\">en plateau</span></strong></td><td><span>Typhoïde</span> au 3ᵉ septénaire ; <span class=\"nc-green_bg\">viroses</span> (dengue, chikungunya, <span><span class=\"nc-green_bg\">primo-infection</span></span><span class=\"nc-green_bg\"> </span><span><span class=\"nc-green_bg\">VIH</span></span>) ; <span class=\"nc-orange_bg\">schistosomose</span></td></tr>\n          <tr><td><strong><span>Fièvre</span> + signes hémorragiques</strong></td><td><span><span class=\"nc-orange_bg\">Paludisme</span></span> ; <span><span class=\"nc-green_bg\">hépatite</span></span><span class=\"nc-green_bg\"> fulminante</span> ; <span class=\"nc-purple_bg\">leptospirose ictéro-</span><span><span class=\"nc-purple_bg\">hémorragique</span></span> ; dengue et <span class=\"nc-green_bg\">arboviroses</span> hémorragiques ; <span>fièvres hémorragiques virales</span></td></tr>\n        </tbody>\n      </table>\n      <p><span>Les</span> <strong>signes cliniques associés</strong> orientent également :</p>\n      <ul>\n        <li><strong><span>Ictère</span> :</strong> <span>hépatite</span> aiguë ; <span><span class=\"nc-orange_bg\">paludisme</span></span> ; <span class=\"nc-purple_bg\">leptospirose</span></li>\n        <li><strong><span>Hépatomégalie</span> :</strong> <span class=\"nc-red_bg\">typhoïde</span> ; <span>hépatite</span> aiguë ; <span><span class=\"nc-red nc-bold\">paludisme</span></span> ; amoebose ; <span class=\"nc-orange_bg\">schistosomose</span></li>\n        <li><strong><span>Splénomégalie</span> :</strong> <span>paludisme</span> ; brucellose ; <span class=\"nc-red_bg\">typhoïde</span> ; <span class=\"nc-pink nc-bold\">dengue</span></li>\n      </ul></div>"},{"i":"4df4a04ad628","n":175,"o":"175-12","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une fièvre hémorragique virale","q":"Quels sont les points essentiels concernant les modalités de diagnostic d’une fièvre hémorragique virale ?","a":"<div class=\"notion-course\"><p><span>Les</span> <span>fièvres hémorragiques virales (FHV)</span> sont rares mais d'une gravité extrême et hautement contagieuses.</p>\n      <ul>\n        <li><strong>Virus :</strong> <span><span class=\"nc-red nc-bold\">Ebola</span></span>, <span><span class=\"nc-red nc-bold\">Marburg</span></span>, <span><span class=\"nc-red nc-bold\">Lassa</span></span> — ce ne sont <strong>pas</strong> des arboviroses</li>\n        <li><strong>Présentation :</strong> <span><span class=\"nc-blue_bg\">fièvre</span></span> associée à un <span>syndrome hémorragique</span> au retour d'une zone à risque</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Conduite à tenir.</strong> Toute suspicion de FHV impose des <span>précautions complémentaires</span> renforcées pour la protection du patient <strong>et</strong> du personnel : <span>isolement</span> et <span>signalement</span> immédiats. La prise en charge est guidée par le <span><span class=\"nc-blue nc-bold\">Centre National de Référence</span> (CNR) des fièvres hémorragiques virales</span> et <span>Santé publique France</span> — <span>les</span> contacter avant tout prélèvement.</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les fièvres hémorragiques virales n’ont pas toutes le même vecteur ni la même contagiosité. L’absence de saignement n’élimine pas une infection à risque ; l’exposition géographique et clinique déclenche l’alerte, l’isolement adapté et l’avis spécialisé avant les prélèvements usuels.</li></ul></div></div>"},{"i":"9f461fb72b8d","n":175,"o":"175-13","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la typhoïde","q":"Quels sont les points essentiels concernant les éléments du diagnostic clinique et biologique de la typhoïde ?","a":"<div class=\"notion-course\"><p>La <span>fièvre <span class=\"nc-red nc-bold\">typhoïde</span></span> est une infection systémique à transmission oro-fécale, à <strong><span class=\"nc-yellow_bg\">déclaration obl</span><span><span class=\"nc-yellow_bg\">iga</span></span><span class=\"nc-yellow_bg\">toire</span></strong>.</p>\n      <table>\n        <thead><tr><th>Item</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Germe</strong></td><td><span><span class=\"nc-purple_bg\">Salmonella</span> <span class=\"nc-purple_bg\">enterica</span></span> sérotypes <span class=\"nc-purple_bg\">Typhi</span> et <span class=\"nc-purple_bg\">Paratyphi A, B ou C</span> ; <strong>réservoir <span class=\"nc-yellow_bg nc-bold\">strictement humain</span></strong></td></tr>\n          <tr><td><strong><span>Physiopathologie</span></strong></td><td>Franchissement de la barrière intestinale <span class=\"nc-green_bg\">sans la léser</span> → circulation sanguine via le <span class=\"nc-purple_bg\">système lymphatique</span> → lyse <span>bactérienne</span> libérant une <span><span class=\"nc-pink nc-bold\">endotoxine</span></span> responsable des manifestations viscérales</td></tr>\n          <tr><td><strong>Incubation</strong></td><td><span>10 jours à 3 semaines</span></td></tr>\n          <tr><td><strong>Phase d'invasion</strong> (<span>1 semaine</span>)</td><td><span><span class=\"nc-blue_bg\">Fièvre</span></span><span class=\"nc-blue_bg\"> progressivement croissante</span> ; <span>asthénie</span>, <span>anorexie</span>, <span>céphalées</span>, insomnie ; <span><span class=\"nc-yellow_bg\">pouls dissocié</span></span> ; <span><span class=\"nc-blue_bg\">splénomégalie</span></span> (<span>30 %</span>) ; <span class=\"nc-blue_bg\">troubles digestifs</span></td></tr>\n          <tr><td><strong>Phase d'état</strong></td><td><span><span class=\"nc-yellow_bg\">Fièvre</span></span> <span><span class=\"nc-yellow_bg nc-bold\">en plateau</span></span> <span class=\"nc-yellow_bg\">à</span><span><span class=\"nc-yellow_bg\"> 40 °C</span></span> ; <span class=\"nc-yellow_bg\">pouls dissocié</span> ; <span><span class=\"nc-yellow_bg\">tuphos</span></span> (inversion du rythme nycthéméral, prostration, <span>obnubilation</span>) ; <span>diarrhée « <span class=\"nc-blue_bg nc-bold\">jus de melon</span> »</span> (2/3 des cas) ; exanthème lenticulaire roséoliforme du tronc (1/3) ; <span><span class=\"nc-orange_bg\">angine de Duguet</span></span> (ulcérations des <span class=\"nc-blue nc-bold\">piliers antérieurs</span> et du <span class=\"nc-blue nc-bold\">voile du palais</span>,<span> 10 %</span>)</td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span><span class=\"nc-blue_bg\">Leuco-neutropénie</span></span> ; <span><span class=\"nc-blue_bg\">CRP élevée</span></span></td></tr>\n          <tr><td><strong>Confirmation</strong></td><td><span>Hémocultures</span></td></tr>\n          <tr><td><strong>Complications</strong></td><td><strong><span class=\"nc-red nc-bold\">Digestives</span> :</strong> <span><span class=\"nc-red nc-bold\">hémorragies</span> <span class=\"nc-red nc-bold\">digestives</span></span> ; <span>perforations digestives</span><br><strong>Toxiniques :</strong> <span class=\"nc-red nc-bold\">myocardite</span> ; <span>encéphalite</span><br><strong>Septiques :</strong> <span class=\"nc-red_bg\">localisations septiques secondaires</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> La <span><span class=\"nc-yellow_bg\">fièvre</span></span> typhoïde est une <strong>maladie à <span class=\"nc-yellow_bg\">déclaration obl</span><span><span class=\"nc-yellow_bg\">iga</span></span><span class=\"nc-yellow_bg\">toire</span></strong> ; le traitement repose sur une C<span <span=\"\">&gt;3</span>G parentérale en probabiliste, secondairement adaptée à l'<span>antibiogramme</span>.</div></div>"},{"i":"01735f626103","n":175,"o":"175-16","u":"Diagnostic positif","t":"Savoir évoquer puis confirmer le diagnostic des parasitoses intestinales","q":"Quels sont les points essentiels concernant évoquer puis confirmer le diagnostic des parasitoses intestinales ?","a":"<div class=\"notion-course\"><p>Le diagnostic des <span class=\"nc-red nc-bold\">parasitoses intestinales</span> suit deux temps : <strong>évoquer</strong>, puis <strong>confirmer</strong>.</p>\n      <p><strong>Évoquer</strong> devant :</p>\n      <ul>\n        <li>Une <span>diarrhée prolongée non fébrile</span> au retour des tropiques (<span><span class=\"nc-red nc-bold\">giardose</span></span> ++)</li>\n        <li>Une <span>hyperéosinophilie</span> sanguine → oriente vers une <span>helminthose</span></li>\n        <li>Un contexte d'exposition (baignade en eau douce → <span>schistosomose</span>)</li>\n      </ul>\n      <p><strong>Confirmer</strong> par :</p>\n      <ul>\n        <li><span><span class=\"nc-blue\">Examen parasitologique des selles</span></span> (à répéter) — recherche de kystes, œufs ou larves</li>\n        <li><span><span class=\"nc-blue_bg\">Sérologie</span></span>, utile notamment en phase précoce</li>\n        <li>Si les examens sont négatifs mais la suspicion persistante : compléter ou répéter les prélèvements et demander un avis. Le <span class=\"nc-pink\">métronidazole</span> ne couvre pas toutes les parasitoses et n’est pas un traitement automatique de toute diarrhée inexpliquée.</li>\n        <li><span>Endoscopie</span> (rectos<span>igm</span>oïdoscopie) en dernier recours</li>\n      </ul>\n      <p>Principales <span>protozooses</span> intestinales : <span><span class=\"nc-red nc-bold\">giardose</span></span>, <span>amoebose à <em>Entamoeba histolytica</em></span>, <span><span class=\"nc-red nc-bold\">cyclosporose</span></span> — traitement par <span><span class=\"nc-pink\">métronidazole</span></span> pour l'amoebose.</p></div>"},{"i":"3f5ae2309bda","n":175,"o":"175-17","u":"Examens complémentaires","t":"Connaître les modalités de prescription des recherches parasitologiques dans des contextes évocateurs (schistosomoses, helminthoses digestives, protozooses digestives)","q":"Quels sont les points essentiels concernant les modalités de prescription des recherches parasitologiques dans des contextes évocateurs (schistosomoses, helminthoses digestives, protozooses digestives) ?","a":"<div class=\"notion-course\"><p><span>Les</span> recherches parasitologiques se prescrivent dans un <strong>contexte évocateur</strong> (exposition, symptômes, hyperéosinophilie) et selon le parasite suspecté.</p>\n      <table>\n        <thead><tr><th>Contexte</th><th>Modalités de prescription</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-purple_bg\">Schistosomoses</span></span></strong></td>\n            <td><strong>Phase d'invasion :</strong> <span>sérologie</span><br><strong>Phase d'état :</strong> recherche d'œufs par microscopie ou <span><span class=\"nc-blue nc-bold\">TAAN</span></span> sur <span><span class=\"nc-blue nc-bold\">urines 3 jours de suite</span></span>, <span><span class=\"nc-blue nc-bold\">selles</span></span>, et <span><span class=\"nc-blue nc-bold\">biopsies par voie endoscopique</span></span> (vessie, rectum)</td>\n          </tr>\n          <tr>\n            <td><strong>Helminthoses digestives</strong></td>\n            <td><span><span class=\"nc-blue\">Examen parasitologique des selles</span></span> ; recherche d'une <span>hyperéosinophilie</span> sanguine d'orientation</td>\n          </tr>\n          <tr>\n            <td><strong>Protozooses digestives</strong></td>\n            <td><span><span class=\"nc-blue\">Examen parasitologique des selles</span></span> répété (<span class=\"nc-red nc-bold\">giardose</span>, amoebose, <span class=\"nc-red nc-bold\">cyclosporose</span>) ; <span>TAAN</span> dans certains cas</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 218 — Eosinophilie</em></p></div>"},{"i":"05580f85261f","n":175,"o":"175-18","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de lésion cutanée au retour du voyage","q":"Quels sont les points essentiels concernant la démarche diagnostique en cas de lésion cutanée au retour du voyage ?","a":"<div class=\"notion-course\"><p>Devant une <strong><span>lésion</span> cutanée au retour d'un voyage</strong>, le type de lésion élémentaire oriente le diagnostic.</p>\n      <table>\n        <thead><tr><th>Type de lésion</th><th>Étiologies à évoquer</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Exanthème fébrile</span></strong></td><td><span><span class=\"nc-green_bg\">Primo-infection VIH</span></span> ; <span class=\"nc-green_bg\">arboviroses</span> (dengue, chikungunya, zika) ; <span class=\"nc-purple_bg\">rickettsiose</span> ; <span class=\"nc-purple_bg\">leptospirose</span> ; <span>allergie</span> médicamenteuse</td></tr>\n          <tr><td><strong><span><span class=\"nc-yellow_bg\">Escarre d'inoculation</span></span></strong></td><td><span>Rickettsiose</span></td></tr>\n          <tr><td><strong><span>Lésions urticariennes</span></strong></td><td><span><span class=\"nc-orange_bg\">Schistosomose</span></span><span class=\"nc-orange_bg\"> en phase d'invasion</span> ; <span>hépatite</span> <span>virale</span> en phase pré-ictérique ; <span>allergie</span> médicamenteuse</td></tr>\n          <tr><td><strong>Maladies tropicales localisées à la peau</strong></td><td><span><span class=\"nc-orange_bg\">Leishmaniose cutanée</span></span> (<span>ulcération</span> d'<span>évolution</span> chronique, lésion nodulaire) ; <span><span class=\"nc-orange_bg\">larva migrans cutanée</span></span><span class=\"nc-orange_bg\"> ankylostomienne</span> ; <span><span class=\"nc-orange_bg\">myiase</span></span> (nodules non nécrotiques) ; <span><span class=\"nc-blue_bg\">prurigo</span></span><span class=\"nc-blue_bg\"> après piqûre d'insecte</span></td></tr>\n        </tbody>\n      </table></div>"},{"i":"3b45720d4c89","n":175,"o":"175-19","u":"Étiologies","t":"Connaître les principales dermatoses d’importation","q":"Quels sont les points essentiels concernant les principales dermatoses d’importation ?","a":"<div class=\"notion-course\"><p><span>Les</span> <strong>dermatoses d'importation</strong> se reconnaissent au type de <span>lésion</span> élémentaire.</p>\n      <table>\n        <thead><tr><th>Lésion</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Œdème</span></strong></td><td><strong>Membres :</strong> <span>dermohypodermite bactérienne</span> (<span>streptocoque</span> du groupe A, <em>S. aureus</em>) ; <span>loase</span> ; filarioses lymphatiques<br><strong>Face :</strong> <span>trichinellose</span> ; <span>maladie de Chagas</span></td></tr>\n          <tr><td><strong>Nodules</strong></td><td><strong>Nécrotiques :</strong> <span>furoncle</span> (<em>S. aureus</em>)<br><strong>Non nécrotiques :</strong> <span><span class=\"nc-orange_bg\">myiase</span></span> ; <span>tungose</span> (puces-chiques)</td></tr>\n          <tr><td><strong><span>Ulcération</span></strong></td><td>Ecthyma (<span>streptocoque</span> A, <em>S. aureus</em>) ; <span>charbon</span> ; trypanosome ; <span>ulcère de Buruli</span> ; <span>leishmaniose</span> (<span>évolution</span> chronique)</td></tr>\n          <tr><td><strong><span>Lésion</span> nodulaire</strong></td><td><span>Leishmaniose</span> ; <span>mycobactéries atypiques</span> ; <span>sporotrichose</span></td></tr>\n          <tr><td><strong>Exanthème</strong></td><td><strong>Urticarien :</strong> invasions helminthiques (<span class=\"nc-orange_bg\">schistosomose</span>, <span>syndrome de Löffler</span>), filariose, <span>primo-infection</span> <span>VIH</span><br><strong>Maculopapuleux :</strong> arboviroses ; <span class=\"nc-green_bg\">primo-infection VIH</span> ; <span class=\"nc-orange_bg\">rickettsioses</span> ; <span>syphilis</span></td></tr>\n          <tr><td><strong><span><span class=\"nc-blue_bg\">Prurit</span></span> diffus</strong></td><td><span>Gale</span> ; piqûres d'arthropodes ; <span><span class=\"nc-green_bg\">primo-infection</span></span><span class=\"nc-green_bg\"> </span><span><span class=\"nc-green_bg\">VIH</span></span> ; <span>onchocercose</span> ; <span><span class=\"nc-blue_bg\">dermatite</span></span> des nageurs</td></tr>\n          <tr><td><strong><span>Larva migrans cutanée</span></strong></td><td>Larbish (ankylostomes du chien ou du chat) ; larva currens (<span>strongyloïdose</span> ; Asie du Sud-Est, Mexique)</td></tr>\n        </tbody>\n      </table>\n      <p>Quelques dermatoses d'importation typiques :</p>\n      \n      \n      \n      </div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d941811f9dbdca39e3e804ae?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
